TEST(EditorApiTests,
     OutlinerSequenceSurvivesViewportFramesAndResetsAtInputOwnerBoundaries) {
  CommandTestHarness harness;
  auto &editor = harness.editor;
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path({}).ok());
  create_selected_box(editor, "Outliner Sequence Box");
  ASSERT_TRUE(editor.commands()
                  .set_shortcut(quader::quader_command::kDeleteSelection,
                                "Ctrl+Alt+F24 G")
                  .ok());
  const auto resolve = [&](std::string_view chord, bool outliner = true) {
    return editor.commands().dispatch_viewport_input_binding(
        single_input_chord(chord), {}, !outliner, false,
        {.outliner_focused = outliner});
  };
  std::vector<quader::QuaderInputChord> suppressed;
  double linear_wheel = 0.0;
  double radial_wheel = 0.0;
  const auto viewport_frame = [&](bool focused) {
    quader::ViewportInputFrame input;
    input.viewport_focused = focused;
    quader::ViewportKeybindingResolver::resolve(
        editor, {}, input, suppressed, linear_wheel, radial_wheel);
  };

  for (const bool viewport_focused : {false, true}) {
    ASSERT_EQ(resolve("Ctrl+Alt+F24").kind,
              quader::QuaderViewportKeybindingDispatch::Kind::PendingChord);
    viewport_frame(viewport_focused);
    ASSERT_TRUE(editor.commands().has_pending_keybinding_chord());
    const auto completion = resolve("G");
    ASSERT_EQ(completion.kind,
              quader::QuaderViewportKeybindingDispatch::Kind::Command);
    EXPECT_EQ(completion.command_id,
              quader::quader_command::kDeleteSelection.string());
  }

  ASSERT_EQ(resolve("Ctrl+Alt+F24").kind,
            quader::QuaderViewportKeybindingDispatch::Kind::PendingChord);
  editor.commands().reset_pending_keybinding_chord();
  EXPECT_EQ(resolve("G").kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  ASSERT_EQ(resolve("Ctrl+Alt+F24").kind,
            quader::QuaderViewportKeybindingDispatch::Kind::PendingChord);
  EXPECT_NE(resolve("G", false).kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_FALSE(editor.commands().has_pending_keybinding_chord());
  ASSERT_EQ(resolve("Ctrl+Alt+F24", false).kind,
            quader::QuaderViewportKeybindingDispatch::Kind::PendingChord);
  viewport_frame(false);
  EXPECT_FALSE(editor.commands().has_pending_keybinding_chord());
}

TEST(EditorApiTests, OutlinerBindingsPreserveCatalogIdentityAndPersistOverrides) {
  CommandTestHarness harness;
  auto &editor = harness.editor;
  const auto path = keybinding_test_path("outliner-scene-context");
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path(path).ok());
  create_selected_box(editor, "Outliner Persistent Binding Box");
  const auto catalog = editor.commands().keybinding_catalog();
  const auto *initial = find_keybinding_catalog_entry(
      catalog, quader::quader_command::kDeleteSelection.string());
  ASSERT_NE(initial, nullptr);
  const auto action = initial->key;
  ASSERT_TRUE(editor.commands().set_action_shortcut(
      action, "Ctrl+Alt+F24 G", quader::QuaderKeybindingConflictPolicy::Reject)
                  .ok());
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path(path).ok());
  const auto loaded_catalog = editor.commands().keybinding_catalog();
  const auto *loaded = find_keybinding_catalog_entry(
      loaded_catalog, quader::quader_command::kDeleteSelection.string());
  ASSERT_NE(loaded, nullptr);
  EXPECT_EQ(loaded->key, action);
  EXPECT_EQ(loaded->when, initial->when);
  EXPECT_EQ(loaded->default_shortcut, initial->default_shortcut);
  EXPECT_EQ(loaded->shortcut, "Ctrl+Alt+F24 G");
  const auto resolve = [&](std::string_view chord) {
    return editor.commands().dispatch_viewport_input_binding(
        single_input_chord(chord), {}, false, false,
        {.outliner_focused = true});
  };
  ASSERT_EQ(resolve("Ctrl+Alt+F24").kind,
            quader::QuaderViewportKeybindingDispatch::Kind::PendingChord);
  ASSERT_TRUE(editor.commands().remove_action_shortcut(action).ok());
  EXPECT_FALSE(editor.commands().has_pending_keybinding_chord());
  EXPECT_EQ(resolve("Ctrl+Alt+F24").kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  ASSERT_TRUE(editor.commands()
                  .reset_action_shortcut(
                      action, quader::QuaderKeybindingConflictPolicy::Reject)
                  .ok());
  const auto restored = resolve(initial->default_shortcut);
  ASSERT_EQ(restored.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(restored.command_id,
            quader::quader_command::kDeleteSelection.string());
}

TEST(EditorApiTests, DisabledKeybindingCandidateFallsThroughOrPassesInput) {
  const std::filesystem::path fallback_path =
      keybinding_test_path("availability-fallback");
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  create_selected_box(editor, "Availability Fallback Box");
  {
    std::ofstream file(fallback_path);
    file << "[\n"
         << "  {\"command\":\""
         << quader::quader_command::kEditUndo.string()
         << "\",\"key\":\"Ctrl+Alt+F24\"},\n"
         << "  {\"command\":\""
         << quader::quader_command::kEditRedo.string()
         << "\",\"key\":\"Ctrl+Alt+F24\"}\n"
         << "]\n";
  }
  ASSERT_TRUE(
      editor.commands().set_keybinding_storage_path(fallback_path).ok());
  quader::ViewportToolState state;
  const quader::QuaderViewportKeybindingDispatch fallback =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Alt+F24"), state, false, false);
  ASSERT_EQ(fallback.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(fallback.command_id,
            quader::quader_command::kEditUndo.string());

  const std::filesystem::path unavailable_path =
      keybinding_test_path("availability-pass-through");
  {
    std::ofstream file(unavailable_path);
    file << "[{\"command\":\""
         << quader::quader_command::kEditCreateInstance.string()
         << "\",\"key\":\"Ctrl+Alt+F23\"}]\n";
  }
  ASSERT_TRUE(
      editor.commands().set_keybinding_storage_path(unavailable_path).ok());
  ASSERT_TRUE(editor.selection().clear().ok());
  const quader::QuaderViewportKeybindingDispatch no_match =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Alt+F23"), state, false, false);
  EXPECT_EQ(no_match.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
}

TEST(EditorApiTests, KeybindingConflictsUseSemanticWhenOverlap) {
    quader::QuaderKeybindingService service;
    service.register_target("navigation.any");
    service.register_target("navigation.fly");
    service.register_target("tool.move");
    service.register_target("tool.box");

    ASSERT_TRUE(service.add_default_keybinding(
        "navigation.any", "F", "viewportFocus && navigation.active"));
    ASSERT_TRUE(service.add_default_keybinding(
        "navigation.fly", "F", "viewportFocus && navigation.flyActive"));
    ASSERT_TRUE(
        service.add_default_keybinding("tool.move", "G", "activeTool.move"));
    ASSERT_TRUE(
        service.add_default_keybinding("tool.box", "G", "activeTool.box"));

    const std::vector<quader::QuaderKeybindingConflict> fly_conflicts =
        service.conflicts_for("F", "viewportFocus && navigation.flyActive");
    EXPECT_NE(std::find_if(fly_conflicts.begin(), fly_conflicts.end(),
                           [](const auto &conflict) {
                             return conflict.target_id == "navigation.any";
                           }),
              fly_conflicts.end());
    EXPECT_NE(std::find_if(fly_conflicts.begin(), fly_conflicts.end(),
                           [](const auto &conflict) {
                             return conflict.target_id == "navigation.fly";
                           }),
              fly_conflicts.end());

    const std::vector<quader::QuaderKeybindingConflict> move_conflicts =
        service.conflicts_for("G", "activeTool.move");
    ASSERT_EQ(move_conflicts.size(), 1u);
    EXPECT_EQ(move_conflicts.front().target_id, "tool.move");
}

TEST(EditorApiTests,
     KeybindingServiceLocksExistingOverridesAndPreservesDisjointFlyRules) {
  quader::QuaderKeybindingService service;
  constexpr std::string_view kReservedWhen =
      "viewportFocus && !textInputActive && !navigation.flyActive";
  constexpr std::string_view kFlyWhen =
      "viewportFocus && !textInputActive && navigation.flyActive";
  ASSERT_TRUE(service.add_default_keybinding(
      "orbit", "MiddleMouseDrag", std::string(kReservedWhen)));
  ASSERT_TRUE(service.add_default_keybinding("tool", "W", "viewportFocus"));
  ASSERT_TRUE(service.add_default_keybinding("fly", "F", std::string(kFlyWhen)));
  ASSERT_TRUE(service.set_user_shortcut("orbit", "Alt+LeftMouseDrag").ok);
  ASSERT_TRUE(service.set_user_shortcut("tool", "Ctrl+K MiddleMouseClick",
                                        "viewportFocus").ok);
  ASSERT_TRUE(service.set_user_shortcut("fly", "MiddleMouseDoubleClick",
                                        std::string(kFlyWhen)).ok);
  const auto legacy = service.user_keybindings();
  EXPECT_EQ(service.shortcut_for("orbit"), "Alt+LeftMouseDrag");
  EXPECT_EQ(service.shortcut_for("tool"), "Ctrl+K MiddleMouseClick");

  service.lock_target("orbit", std::string(kReservedWhen));
  EXPECT_FALSE(service.target_editable("orbit"));
  EXPECT_TRUE(service.target_editable("fly"));
  EXPECT_EQ(service.shortcut_for("orbit"), "MiddleMouseDrag");
  EXPECT_EQ(service.shortcut_for("tool"), "W");
  EXPECT_EQ(service.shortcut_for("fly"), "MiddleMouseDoubleClick");
  EXPECT_FALSE(service.set_user_shortcut("orbit", "F19").ok);
  EXPECT_FALSE(service.remove_user_shortcut("orbit").ok);
  EXPECT_FALSE(service.reset_user_shortcut("orbit").ok);
  EXPECT_FALSE(service.set_user_shortcut("tool", "MiddleMouseDrag F19",
                                         "viewportFocus").ok);
  EXPECT_FALSE(service.replace_user_keybindings(legacy).ok);
  ASSERT_TRUE(service.adopt_loaded_user_keybindings(legacy).ok);
  const auto retained = service.user_keybindings();
  ASSERT_EQ(retained.size(), 1u);
  EXPECT_EQ(retained.front().target_id, "fly");
  EXPECT_EQ(service.shortcut_for("orbit"), "MiddleMouseDrag");
  EXPECT_EQ(service.shortcut_for("tool"), "W");
  EXPECT_EQ(service.shortcut_for("fly"), "MiddleMouseDoubleClick");

  quader::QuaderKeybindingContext context;
  context.set("viewportFocus", true);
  EXPECT_EQ(service.dispatch(single_input_chord("MiddleMouseDrag"), context)
                .target_id,
            "orbit");
  context.set("navigation.active", true);
  context.set("navigation.flyActive", true);
  EXPECT_EQ(service.dispatch(single_input_chord("MiddleMouseDoubleClick"), context)
                .target_id,
            "fly");
}

TEST(EditorApiTests,
     PendingKeybindingChordExpiresBeforeDispatchingTheNextShortcut) {
  quader::QuaderKeybindingService service;
  ASSERT_TRUE(service.add_default_keybinding(
      "sequence", "Ctrl+K D F", "sequenceMode"));
  ASSERT_TRUE(
      service.add_default_keybinding("single", "D", "singleMode"));

  quader::QuaderKeybindingContext sequence_context;
  sequence_context.set("sequenceMode", true);
  quader::QuaderKeybindingContext single_context;
  single_context.set("singleMode", true);

  const quader::QuaderKeybindingService::TimePoint started{};
  const auto prefix = service.dispatch_at(
      single_input_chord("Ctrl+K"), sequence_context, started);
  ASSERT_EQ(prefix.kind,
            quader::QuaderKeybindingDispatch::Kind::PendingChord);
  EXPECT_TRUE(service.has_pending_chord_at(
      started + quader::QuaderKeybindingService::pending_chord_timeout() -
      std::chrono::milliseconds{1}));

  const auto deadline =
      started + quader::QuaderKeybindingService::pending_chord_timeout();
  EXPECT_FALSE(service.has_pending_chord_at(deadline));
  const auto later = service.dispatch_at(single_input_chord("D"),
                                         single_context, deadline);
  ASSERT_EQ(later.kind, quader::QuaderKeybindingDispatch::Kind::ExactMatch);
  EXPECT_EQ(later.target_id, "single");
  EXPECT_FALSE(service.has_pending_chord_at(deadline));
}

TEST(EditorApiTests,
     PendingKeybindingChordContinuesBeforeDeadlineAndResetsOnRebind) {
  quader::QuaderKeybindingService service;
  ASSERT_TRUE(service.add_default_keybinding(
      "sequence", "Ctrl+K D F", "sequenceMode"));
  ASSERT_TRUE(service.add_default_keybinding("single", "D", "sequenceMode"));

  quader::QuaderKeybindingContext context;
  context.set("sequenceMode", true);
  const quader::QuaderKeybindingService::TimePoint started{};
  ASSERT_EQ(service
                .dispatch_at(single_input_chord("Ctrl+K"), context, started)
                .kind,
            quader::QuaderKeybindingDispatch::Kind::PendingChord);

  const auto before_deadline =
      started + quader::QuaderKeybindingService::pending_chord_timeout() -
      std::chrono::milliseconds{1};
  const auto intermediate = service.dispatch_at(
      single_input_chord("D"), context, before_deadline);
  ASSERT_EQ(intermediate.kind,
            quader::QuaderKeybindingDispatch::Kind::PendingChord);
  EXPECT_TRUE(service.has_pending_chord_at(before_deadline));

  const auto final_chord =
      before_deadline +
      quader::QuaderKeybindingService::pending_chord_timeout() -
      std::chrono::milliseconds{1};
  const auto continuation =
      service.dispatch_at(single_input_chord("F"), context, final_chord);
  ASSERT_EQ(continuation.kind,
            quader::QuaderKeybindingDispatch::Kind::ExactMatch);
  EXPECT_EQ(continuation.target_id, "sequence");
  EXPECT_FALSE(service.has_pending_chord_at(final_chord));

  const auto restarted = final_chord + std::chrono::milliseconds{1};
  ASSERT_EQ(service
                .dispatch_at(single_input_chord("Ctrl+K"), context, restarted)
                .kind,
            quader::QuaderKeybindingDispatch::Kind::PendingChord);
  service.reset_pending_chord();
  EXPECT_FALSE(service.has_pending_chord_at(restarted));
  EXPECT_EQ(service.dispatch_at(single_input_chord("D"), context, restarted)
                .target_id,
            "single");

  ASSERT_EQ(service
                .dispatch_at(single_input_chord("Ctrl+K"), context, restarted)
                .kind,
            quader::QuaderKeybindingDispatch::Kind::PendingChord);
  const quader::QuaderKeybindingMutationResult rebound =
      service.set_user_shortcut("sequence", "Ctrl+K F", "sequenceMode");
  ASSERT_TRUE(rebound.ok) << rebound.message;
  ASSERT_TRUE(rebound.changed);
  EXPECT_FALSE(service.has_pending_chord_at(restarted));
  EXPECT_EQ(service.dispatch_at(single_input_chord("D"), context, restarted)
                .target_id,
            "single");
}

TEST(EditorApiTests, PersistedKeybindingsRejectUnknownTargets) {
  const std::filesystem::path unknown_path =
      keybinding_test_path("unknown-target");
  {
    std::ofstream file(unknown_path);
    file << "[{\"command\":\"missing.command\",\"key\":\"Ctrl+M\"}]\n";
  }

    CommandTestHarness harness;
    quader::QuaderEditorApi& editor = harness.editor;
    const quader::QuaderApiVoidResult loaded =
        editor.commands().set_keybinding_storage_path(unknown_path);
    EXPECT_FALSE(loaded.ok());
    EXPECT_NE(loaded.error_message().find("unknown command id"),
              std::string::npos);

    const std::filesystem::path unknown_removal_path =
        keybinding_test_path("unknown-removal-target");
    {
      std::ofstream file(unknown_removal_path);
      file << "[{\"command\":\"-missing.command\"}]\n";
    }

    CommandTestHarness removal_harness;
    quader::QuaderEditorApi &removal_editor = removal_harness.editor;
    const quader::QuaderApiVoidResult loaded_removal =
        removal_editor.commands().set_keybinding_storage_path(
            unknown_removal_path);
    EXPECT_FALSE(loaded_removal.ok());
    EXPECT_NE(loaded_removal.error_message().find("unknown command id"),
              std::string::npos);
}

TEST(EditorApiTests, ViewportKeybindingsResolveContextAndUserOverrides) {
  const std::filesystem::path path = keybinding_test_path("viewport");
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path(path).ok());
  create_selected_box(editor, "Undo Shortcut Box");

  quader::ViewportToolState state;
  quader::ViewportShortcut shortcut;
  const std::string face_selection_target =
      editor.commands().keybinding_target_id_for_selection_mode(
          quader::QuaderSelectionMode::Face);
  EXPECT_EQ(face_selection_target,
            quader::quader_viewport_selection_mode_target_id("face"));
  EXPECT_EQ(editor.commands().shortcut_for(face_selection_target), "3");
  ASSERT_TRUE(editor.commands().resolve_viewport_shortcut(
      quader::ViewportKey::Number3, {}, state, true, false, shortcut));
  EXPECT_EQ(shortcut.kind, quader::ViewportShortcutKind::SetSelectionMode);
  EXPECT_EQ(shortcut.selection_mode, quader::ViewportSelectionMode::Face);

  ASSERT_TRUE(
      editor.preferences()
          .set_shortcut(face_selection_target, "Ctrl+Alt+3")
          .ok());
  EXPECT_EQ(editor.commands().shortcut_for(face_selection_target),
            "Ctrl+Alt+3");
  shortcut = {};
  EXPECT_FALSE(editor.commands().resolve_viewport_shortcut(
      quader::ViewportKey::Number3, {}, state, true, false, shortcut));
  ASSERT_TRUE(editor.commands().resolve_viewport_shortcut(
      quader::ViewportKey::Number3, {.primary = true, .alt = true}, state, true,
      false, shortcut));
  EXPECT_EQ(shortcut.kind, quader::ViewportShortcutKind::SetSelectionMode);
  EXPECT_EQ(shortcut.selection_mode, quader::ViewportSelectionMode::Face);
  ASSERT_TRUE(editor.preferences().reset_shortcut(face_selection_target).ok());
  EXPECT_EQ(editor.commands().shortcut_for(face_selection_target), "3");

  ASSERT_TRUE(editor.preferences()
                  .set_shortcut(quader::quader_command::kEditUndo, "Ctrl+U")
                  .ok());
  const quader::QuaderViewportKeybindingDispatch dispatch =
      editor.commands().dispatch_viewport_keybinding(
          quader::ViewportKey::U, {.primary = true}, state, true, false);
  EXPECT_EQ(dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(dispatch.command_id, quader::quader_command::kEditUndo.string());

  shortcut = {};
  EXPECT_FALSE(editor.commands().resolve_viewport_shortcut(
      quader::ViewportKey::Number3, {.primary = true}, state, true, true,
      shortcut));
}

TEST(EditorApiTests,
     CursorPopupBindingsPreserveZPrecedenceModifiersAndPersistence) {
  constexpr std::string_view kAddPopup = "viewport.add_popup";
  constexpr std::string_view kShadingPopup = "viewport.shading_popup";
  constexpr std::string_view kLinearArrayZ =
      "viewport.linear_array.constraint_z";
  const std::filesystem::path path =
      keybinding_test_path("viewport-cursor-popups");
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path(path).ok());
  (void)create_selected_box(editor, "Popup Shortcut History A");
  (void)create_selected_box(editor, "Popup Shortcut History B");
  ASSERT_TRUE(editor.history().undo().ok());
  ASSERT_TRUE(editor.history().can_undo());
  ASSERT_TRUE(editor.history().can_redo());

  EXPECT_EQ(editor.commands().shortcut_for(kAddPopup), "Shift+A");
  EXPECT_EQ(editor.commands().shortcut_for(kShadingPopup), "Z");

  const auto expect_popup = [](quader::QuaderEditorApi &owner,
                               std::string_view binding,
                               quader::ViewportShortcutKind expected) {
    const quader::QuaderViewportKeybindingDispatch dispatch =
        owner.commands().dispatch_viewport_input_binding(
            single_input_chord(binding), {}, true, false);
    ASSERT_EQ(dispatch.kind,
              quader::QuaderViewportKeybindingDispatch::Kind::ViewportShortcut)
        << binding;
    EXPECT_EQ(dispatch.shortcut.kind, expected) << binding;
  };
  expect_popup(editor, "Shift+A", quader::ViewportShortcutKind::AddPopup);
  expect_popup(editor, "Z", quader::ViewportShortcutKind::ShadingPopup);

  for (const std::string_view binding : {"Shift+A", "Z"}) {
    SCOPED_TRACE(binding);
    EXPECT_EQ(editor.commands()
                  .dispatch_viewport_input_binding(
                      single_input_chord(binding), {}, false, false)
                  .kind,
              quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
    EXPECT_EQ(editor.commands()
                  .dispatch_viewport_input_binding(
                      single_input_chord(binding), {}, true, true)
                  .kind,
              quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
    EXPECT_EQ(editor.commands()
                  .dispatch_viewport_input_binding(
                      single_input_chord(binding), {}, true, false,
                      {.navigation_active = true})
                  .kind,
              quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  }

  quader::ViewportToolState linear_array_state{
      .active_tool = quader::ViewportToolId::LinearArray,
  };
  const quader::QuaderViewportKeybindingDispatch linear_array_z =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Z"), linear_array_state, true, false);
  ASSERT_EQ(
      linear_array_z.kind,
      quader::QuaderViewportKeybindingDispatch::Kind::ViewportInputAction);
  EXPECT_EQ(linear_array_z.action,
            quader::ViewportInputActionKind::ToolConstraintZ);

  const quader::QuaderViewportKeybindingDispatch mirror_z =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Shift+Z"), linear_array_state, true, false);
  ASSERT_EQ(mirror_z.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(mirror_z.command_id,
            quader::quader_command::kModelingMirrorSelectionZ.string());

  const quader::QuaderViewportKeybindingDispatch undo =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Z"), linear_array_state, true, false);
  ASSERT_EQ(undo.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(undo.command_id, quader::quader_command::kEditUndo.string());
  const quader::QuaderViewportKeybindingDispatch redo =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Shift+Z"), linear_array_state, true,
          false);
  ASSERT_EQ(redo.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(redo.command_id, quader::quader_command::kEditRedo.string());

  const auto catalog = editor.commands().keybinding_catalog();
  const auto *add = find_keybinding_catalog_entry(catalog, kAddPopup);
  const auto *shading =
      find_keybinding_catalog_entry(catalog, kShadingPopup);
  ASSERT_NE(add, nullptr);
  ASSERT_NE(shading, nullptr);
  EXPECT_EQ(add->default_shortcut, "Shift+A");
  EXPECT_EQ(shading->default_shortcut, "Z");
  const quader::QuaderKeybindingAssignmentAnalysis z_conflicts =
      editor.commands().analyze_shortcut_assignment(add->key, "Z");
  ASSERT_TRUE(z_conflicts.ok) << z_conflicts.message;
  const auto has_exact_conflict = [&](std::string_view target_id) {
    return std::any_of(
        z_conflicts.conflicts.begin(), z_conflicts.conflicts.end(),
        [&](const quader::QuaderKeybindingCollision &collision) {
          return collision.target_id == target_id &&
                 collision.kind ==
                     quader::QuaderKeybindingCollisionKind::ExactConflict;
        });
  };
  EXPECT_TRUE(has_exact_conflict(kShadingPopup));
  EXPECT_TRUE(has_exact_conflict(kLinearArrayZ));
  const quader::QuaderApiVoidResult rejected_z =
      editor.preferences().set_action_shortcut(
          add->key, "Z", quader::QuaderKeybindingConflictPolicy::Reject);
  EXPECT_FALSE(rejected_z.ok());
  EXPECT_FALSE(rejected_z.changed());
  EXPECT_EQ(editor.commands().shortcut_for(kAddPopup), "Shift+A");
  EXPECT_EQ(editor.commands().shortcut_for(kShadingPopup), "Z");

  ASSERT_TRUE(
      editor.preferences().set_shortcut(kAddPopup, "Ctrl+Alt+F20").ok());
  ASSERT_TRUE(editor.preferences()
                  .set_shortcut(kShadingPopup, "Ctrl+Alt+F21")
                  .ok());
  CommandTestHarness reloaded_harness;
  quader::QuaderEditorApi &reloaded = reloaded_harness.editor;
  ASSERT_TRUE(reloaded.commands().set_keybinding_storage_path(path).ok());
  EXPECT_EQ(reloaded.commands().shortcut_for(kAddPopup), "Ctrl+Alt+F20");
  EXPECT_EQ(reloaded.commands().shortcut_for(kShadingPopup), "Ctrl+Alt+F21");
  EXPECT_EQ(reloaded.commands()
                .dispatch_viewport_input_binding(single_input_chord("Shift+A"),
                                                 {}, true, false)
                .kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  EXPECT_EQ(reloaded.commands()
                .dispatch_viewport_input_binding(single_input_chord("Z"), {},
                                                 true, false)
                .kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  expect_popup(reloaded, "Ctrl+Alt+F20",
               quader::ViewportShortcutKind::AddPopup);
  expect_popup(reloaded, "Ctrl+Alt+F21",
               quader::ViewportShortcutKind::ShadingPopup);

  ASSERT_TRUE(reloaded.preferences().remove_shortcut(kAddPopup).ok());
  ASSERT_TRUE(reloaded.preferences().remove_shortcut(kShadingPopup).ok());
  CommandTestHarness removed_harness;
  quader::QuaderEditorApi &removed = removed_harness.editor;
  ASSERT_TRUE(removed.commands().set_keybinding_storage_path(path).ok());
  EXPECT_TRUE(removed.commands().shortcut_for(kAddPopup).empty());
  EXPECT_TRUE(removed.commands().shortcut_for(kShadingPopup).empty());

  ASSERT_TRUE(removed.preferences().reset_shortcut(kAddPopup).ok());
  ASSERT_TRUE(removed.preferences().reset_shortcut(kShadingPopup).ok());
  CommandTestHarness reset_harness;
  quader::QuaderEditorApi &reset = reset_harness.editor;
  ASSERT_TRUE(reset.commands().set_keybinding_storage_path(path).ok());
  EXPECT_EQ(reset.commands().shortcut_for(kAddPopup), "Shift+A");
  EXPECT_EQ(reset.commands().shortcut_for(kShadingPopup), "Z");
  expect_popup(reset, "Shift+A", quader::ViewportShortcutKind::AddPopup);
  expect_popup(reset, "Z", quader::ViewportShortcutKind::ShadingPopup);
  std::filesystem::remove(path);
}

TEST(EditorApiTests,
     MarkingMenuBindingsPreserveInitiatingChordScopesAndSelectOverrides) {
  constexpr std::string_view kMarkingMenu = "viewport.marking_menu";
  const std::filesystem::path path =
      keybinding_test_path("viewport-marking-menu");
  CommandTestHarness harness;
  auto &editor = harness.editor;
  auto &commands = editor.commands();
  ASSERT_TRUE(commands.set_keybinding_storage_path(path).ok());
  using Kind = quader::QuaderViewportKeybindingDispatch::Kind;
  const quader::ViewportToolState state{
      .active_tool = quader::ViewportToolId::Move};

  EXPECT_EQ(commands.shortcut_for(kMarkingMenu), "Q");
  EXPECT_TRUE(commands.shortcut_for(
      quader::quader_command::kToolsActivateSelect).empty());
  const auto expect_marking_menu = [&](std::string_view binding) {
    const auto chord = single_input_chord(binding);
    const auto dispatch = commands.dispatch_viewport_input_binding(
        chord, state, true, false);
    ASSERT_EQ(dispatch.kind, Kind::ViewportShortcut);
    EXPECT_EQ(dispatch.shortcut.kind,
              quader::ViewportShortcutKind::MarkingMenu);
    ASSERT_TRUE(dispatch.shortcut.initiating_chord.has_value());
    EXPECT_EQ(*dispatch.shortcut.initiating_chord, chord);
  };
  expect_marking_menu("Q");

  const auto lasso = commands.dispatch_viewport_input_binding(
      single_input_chord("Shift+Q"), state, true, false);
  ASSERT_EQ(lasso.kind, Kind::ViewportShortcut);
  EXPECT_EQ(lasso.shortcut.kind, quader::ViewportShortcutKind::ActivateTool);
  EXPECT_EQ(lasso.shortcut.tool, quader::ViewportToolId::LassoSelect);

  for (const std::string_view binding : {"Q", "Ctrl+Alt+F20"}) {
    SCOPED_TRACE(binding);
    ASSERT_TRUE(editor.preferences()
                    .set_shortcut(kMarkingMenu, std::string(binding)).ok());
    expect_marking_menu(binding);
    const auto chord = single_input_chord(binding);
    EXPECT_EQ(commands.dispatch_viewport_input_binding(
                  chord, state, false, false, {.editor_focused = true}).kind,
              Kind::NoMatch);
    EXPECT_EQ(commands.dispatch_viewport_input_binding(
                  chord, state, true, true).kind,
              Kind::NoMatch);
    EXPECT_EQ(commands.dispatch_viewport_input_binding(
                  chord, state, true, false, {.navigation_active = true}).kind,
              Kind::NoMatch);
  }
  EXPECT_EQ(commands.dispatch_viewport_input_binding(
                single_input_chord("Q"), state, true, false).kind,
            Kind::NoMatch);

  ASSERT_TRUE(editor.preferences()
                  .set_shortcut(kMarkingMenu, "Ctrl+K Alt+F21").ok());
  EXPECT_EQ(commands.dispatch_viewport_input_binding(
                single_input_chord("Ctrl+K"), state, true, false).kind,
            Kind::PendingChord);
  expect_marking_menu("Alt+F21");
  EXPECT_FALSE(commands.has_pending_keybinding_chord());

  ASSERT_TRUE(editor.preferences()
                  .set_shortcut(quader::quader_command::kToolsActivateSelect,
                                "Q").ok());
  const auto conflicting_reset =
      editor.preferences().reset_shortcut(kMarkingMenu);
  EXPECT_FALSE(conflicting_reset.ok());
  EXPECT_FALSE(conflicting_reset.changed());
  EXPECT_EQ(commands.shortcut_for(kMarkingMenu), "Ctrl+K Alt+F21");
  CommandTestHarness reloaded_harness;
  auto &reloaded = reloaded_harness.editor;
  ASSERT_TRUE(reloaded.commands().set_keybinding_storage_path(path).ok());
  EXPECT_EQ(reloaded.commands().shortcut_for(
                quader::quader_command::kToolsActivateSelect), "Q");
  EXPECT_EQ(reloaded.commands().shortcut_for(kMarkingMenu), "Ctrl+K Alt+F21");
  const auto select = reloaded.commands().dispatch_viewport_input_binding(
      single_input_chord("Q"), state, true, false);
  ASSERT_EQ(select.kind, Kind::ViewportShortcut);
  EXPECT_EQ(select.shortcut.kind, quader::ViewportShortcutKind::ActivateTool);
  EXPECT_EQ(select.shortcut.tool, quader::ViewportToolId::Select);
  std::filesystem::remove(path);
}

TEST(EditorApiTests,
     AssetBrowserDefaultPreservesStoredMappingsSequencesAndUnassignments) {
  /// Owns the uniquely named project and override file used by this test.
  struct TemporaryProject {
    std::filesystem::path root = std::filesystem::temp_directory_path() /
        ("quader-asset-bindings-" + std::to_string(
            std::chrono::steady_clock::now().time_since_epoch().count()));
    ~TemporaryProject() {
      std::error_code ignored;
      std::filesystem::remove_all(root, ignored);
    }
  } temporary;
  ASSERT_TRUE(std::filesystem::create_directories(temporary.root / "Project"));
  const auto path = temporary.root / "keybindings.json";
  quader::ProjectSession project;
  quader::QuaderEditorApi editor(project);
  ASSERT_TRUE(editor.project().create(temporary.root / "Project").ok());
  editor.ui().set_runtime_hooks({.toggle_asset_browser = [] {
    return quader::QuaderApiVoidResult{.ok = true, .changed = true};
  }});
  ASSERT_TRUE(editor.commands().descriptor(
      quader::quader_command::kUiAssetBrowser)->enabled);
  const auto load = [&](const std::string &contents) {
    {
      std::ofstream stored(path);
      ASSERT_TRUE(stored.is_open());
      stored << contents;
    }
    const auto result = editor.commands().set_keybinding_storage_path(path);
    ASSERT_TRUE(result.ok()) << result.error_message();
    EXPECT_EQ(read_text_file(path), contents)
        << "Loading compiled additions must not rewrite stored overrides";
  };

  load(R"([{"command":"viewport.selection_mode.face","key":"Ctrl+Space"},{"command":"-edit.undo"}])");
  ASSERT_FALSE(HasFatalFailure());
  const auto chord = single_input_chord("Ctrl+Space");
  EXPECT_FALSE(editor.commands().resolve_immediate_global_command(
      chord, {}, false).has_value());
  const auto selection = editor.commands().dispatch_viewport_input_binding(
      chord, {}, true, false);
  ASSERT_EQ(selection.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::ViewportShortcut);
  EXPECT_EQ(selection.shortcut.kind, quader::ViewportShortcutKind::SetSelectionMode);
  EXPECT_EQ(selection.shortcut.selection_mode, quader::ViewportSelectionMode::Face);
  EXPECT_TRUE(editor.commands().shortcut_for(quader::quader_command::kEditUndo).empty());

  load(R"([{"command":"viewport.selection_mode.face","key":"Ctrl+Space Ctrl+S"},{"command":"-edit.undo"}])");
  ASSERT_FALSE(HasFatalFailure());
  EXPECT_FALSE(editor.commands().resolve_immediate_global_command(
      chord, {}, false).has_value());
  EXPECT_EQ(editor.commands().dispatch_viewport_input_binding(
                chord, {}, true, false).kind,
            quader::QuaderViewportKeybindingDispatch::Kind::PendingChord);
  EXPECT_FALSE(editor.commands().resolve_immediate_global_command(
      single_input_chord("Ctrl+S"), {}, false).has_value());
  const auto sequence = editor.commands().dispatch_viewport_input_binding(
      single_input_chord("Ctrl+S"), {}, true, false);
  ASSERT_EQ(sequence.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::ViewportShortcut);
  EXPECT_EQ(sequence.shortcut.selection_mode, quader::ViewportSelectionMode::Face);

  load(R"([{"command":"ui.asset_browser","key":"Ctrl+Alt+Space"},{"command":"-edit.undo"}])");
  ASSERT_FALSE(HasFatalFailure());
  EXPECT_EQ(editor.commands().shortcut_for(quader::quader_command::kUiAssetBrowser),
            "Ctrl+Alt+Space");
  EXPECT_FALSE(editor.commands().resolve_immediate_global_command(
      chord, {}, false).has_value());
  EXPECT_EQ(editor.commands().resolve_immediate_global_command(
                single_input_chord("Ctrl+Alt+Space"), {}, false),
            std::optional<std::string>{"ui.asset_browser"});

  load(R"([{"command":"-ui.asset_browser"},{"command":"edit.undo","key":"Ctrl+Space"}])");
  ASSERT_FALSE(HasFatalFailure());
  EXPECT_TRUE(editor.commands().shortcut_for(
      quader::quader_command::kUiAssetBrowser).empty());
  EXPECT_EQ(editor.commands().shortcut_for(quader::quader_command::kEditUndo),
            "Ctrl+Space");
}

TEST(EditorApiTests,
     AssetBrowserInputOwnsCanonicalClipboardBindingsAcrossSceneModes) {
  CommandTestHarness harness;
  auto &commands = harness.editor.commands();
  ASSERT_TRUE(commands.set_keybinding_storage_path({}).ok());
  const quader::QuaderViewportKeybindingContext browser_context{
      .navigation_active = true,
      .editor_focused = true,
      .asset_browser_focused = true};
  const std::array bindings{
      std::pair{"Ctrl+X", quader::quader_command::kCutSelection},
      std::pair{"Ctrl+C", quader::quader_command::kCopySelection},
      std::pair{"Ctrl+V", quader::quader_command::kPasteSelection},
      std::pair{"Ctrl+D", quader::quader_command::kDuplicateSelection},
      std::pair{"Delete", quader::quader_command::kDeleteSelection}};
  for (const auto mode : {quader::ViewportSelectionMode::Vertex,
                          quader::ViewportSelectionMode::Edge,
                          quader::ViewportSelectionMode::Face,
                          quader::ViewportSelectionMode::Object,
                          quader::ViewportSelectionMode::Group}) {
    const quader::ViewportToolState state{.selection_mode = mode};
    for (const auto &[shortcut, command] : bindings) {
      SCOPED_TRACE(shortcut);
      const auto dispatch = commands.dispatch_viewport_input_binding(
          single_input_chord(shortcut), state, false, false, browser_context);
      ASSERT_EQ(dispatch.kind,
                quader::QuaderViewportKeybindingDispatch::Kind::Command);
      EXPECT_EQ(dispatch.command_id, command.string());
      EXPECT_EQ(commands.dispatch_viewport_input_binding(
                    single_input_chord(shortcut), state, false, true,
                    browser_context).kind,
                quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
    }
  }
  for (const char *shortcut : {"Ctrl+Z", "Shift+B", "1"}) {
    EXPECT_EQ(commands.dispatch_viewport_input_binding(
                  single_input_chord(shortcut), {}, false, false,
                  browser_context).kind,
              quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  }
  for (const auto &[shortcut, command] : {
           std::pair{"Ctrl+N", quader::quader_command::kSceneDocumentNew},
           std::pair{"Ctrl+S", quader::quader_command::kSceneDocumentSave}}) {
    const auto dispatch = commands.dispatch_viewport_input_binding(
        single_input_chord(shortcut), {}, false, false, browser_context);
    EXPECT_EQ(dispatch.command_id, command.string());
  }
  EXPECT_EQ(commands.dispatch_viewport_input_binding(
                single_input_chord("Ctrl+S"), {}, false, true,
                browser_context).command_id,
            quader::quader_command::kSceneDocumentSave.string());

  ASSERT_TRUE(commands.set_shortcut(quader::quader_command::kCutSelection,
                                   "Ctrl+K Ctrl+X").ok());
  const auto prefix = single_input_chord("Ctrl+K");
  const auto suffix = single_input_chord("Ctrl+X");
  EXPECT_EQ(commands.resolve_asset_browser_input_binding(prefix, false).kind,
            quader::QuaderViewportKeybindingDispatch::Kind::PendingChord);
  EXPECT_FALSE(commands.has_pending_keybinding_chord());
  EXPECT_EQ(commands.dispatch_viewport_input_binding(
                prefix, {}, false, false, browser_context).kind,
            quader::QuaderViewportKeybindingDispatch::Kind::PendingChord);
  const auto probe = commands.resolve_asset_browser_input_binding(suffix, false);
  EXPECT_EQ(probe.command_id, quader::quader_command::kCutSelection.string());
  EXPECT_TRUE(commands.has_pending_keybinding_chord());
  const auto completed = commands.dispatch_viewport_input_binding(
      suffix, {}, false, false, browser_context);
  EXPECT_EQ(completed.command_id,
            quader::quader_command::kCutSelection.string());
  EXPECT_FALSE(commands.has_pending_keybinding_chord());

  ASSERT_TRUE(commands.remove_shortcut(quader::quader_command::kCutSelection).ok());
  EXPECT_EQ(commands.dispatch_viewport_input_binding(
                prefix, {}, false, false, browser_context).kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
}

TEST(EditorApiTests, GlobalCommandKeybindingsResolveWithAndWithoutViewportFocus) {
  const std::filesystem::path path =
      keybinding_test_path("global-command-shortcuts");
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path(path).ok());
  create_selected_box(editor, "Global Undo Shortcut Box");

  quader::ViewportToolState state;
  const quader::QuaderViewportKeybindingDispatch new_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+N"), state, false, false);
  ASSERT_EQ(new_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(new_dispatch.command_id,
            quader::quader_command::kSceneDocumentNew.string());

  const quader::QuaderViewportKeybindingDispatch open_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+O"), state, false, false);
  ASSERT_EQ(open_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(open_dispatch.command_id,
            quader::quader_command::kSceneDocumentOpen.string());

  const quader::QuaderViewportKeybindingDispatch save_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+S"), state, false, false);
  ASSERT_EQ(save_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(save_dispatch.command_id,
            quader::quader_command::kSceneDocumentSave.string());

  const quader::QuaderViewportKeybindingDispatch save_as_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Alt+S"), state, false, false);
  ASSERT_EQ(save_as_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(save_as_dispatch.command_id,
            quader::quader_command::kSceneDocumentSaveAs.string());

  const quader::QuaderViewportKeybindingDispatch save_all_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Shift+S"), state, false, false);
  ASSERT_EQ(save_all_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(save_all_dispatch.command_id,
            quader::quader_command::kSceneDocumentSaveAll.string());

  const quader::QuaderViewportKeybindingDispatch text_focused_save_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+S"), state, false, true);
  ASSERT_EQ(text_focused_save_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(text_focused_save_dispatch.command_id,
            quader::quader_command::kSceneDocumentSave.string());

  const quader::QuaderViewportKeybindingDispatch
      text_focused_save_as_dispatch =
          editor.commands().dispatch_viewport_input_binding(
              single_input_chord("Ctrl+Alt+S"), state, false, true);
  ASSERT_EQ(text_focused_save_as_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(text_focused_save_as_dispatch.command_id,
            quader::quader_command::kSceneDocumentSaveAs.string());

  const quader::QuaderViewportKeybindingDispatch
      text_focused_save_all_dispatch =
          editor.commands().dispatch_viewport_input_binding(
              single_input_chord("Ctrl+Shift+S"), state, false, true);
  ASSERT_EQ(text_focused_save_all_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(text_focused_save_all_dispatch.command_id,
            quader::quader_command::kSceneDocumentSaveAll.string());

  const quader::QuaderViewportKeybindingDispatch text_focused_undo_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Z"), state, false, true);
  EXPECT_EQ(text_focused_undo_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch)
      << "editing shortcuts must remain owned by the focused text editor";

  const quader::QuaderViewportKeybindingDispatch close_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+W"), state, false, false);
  ASSERT_EQ(close_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(close_dispatch.command_id,
            quader::quader_command::kSceneDocumentClose.string());

  const quader::QuaderViewportKeybindingDispatch next_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Tab"), state, false, false);
  EXPECT_EQ(next_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);

  const quader::QuaderViewportKeybindingDispatch previous_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Shift+Tab"), state, false, false);
  EXPECT_EQ(previous_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);

  const quader::QuaderViewportKeybindingDispatch focused_copy_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+C"), state, true, false);
  ASSERT_EQ(focused_copy_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(focused_copy_dispatch.command_id,
            quader::quader_command::kCopySelection.string());
  EXPECT_NE(focused_copy_dispatch.command_id,
            quader::quader_command::kViewportFrameSelection.string());

  const quader::QuaderViewportKeybindingDispatch focused_cut_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+X"), state, true, false);
  ASSERT_EQ(focused_cut_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(focused_cut_dispatch.command_id,
            quader::quader_command::kCutSelection.string());

#ifndef NDEBUG
  const quader::QuaderViewportKeybindingDispatch dev_copy_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Shift+C"), state, false, false);
  ASSERT_EQ(dev_copy_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(dev_copy_dispatch.command_id,
            quader::quader_command::kDevCopySelectionJson.string());

  const quader::QuaderViewportKeybindingDispatch focused_dev_copy_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Shift+C"), state, true, false);
  ASSERT_EQ(focused_dev_copy_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(focused_dev_copy_dispatch.command_id,
            quader::quader_command::kDevCopySelectionJson.string());
#endif

  const quader::QuaderViewportKeybindingDispatch undo_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Z"), state, false, false);
  ASSERT_EQ(undo_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(undo_dispatch.command_id,
            quader::quader_command::kEditUndo.string());

  ASSERT_TRUE(
      editor.commands().execute(quader::quader_command::kEditUndo).ok());

  const quader::QuaderViewportKeybindingDispatch removed_redo_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Y"), state, false, false);
  EXPECT_EQ(removed_redo_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);

  const quader::QuaderViewportKeybindingDispatch shift_redo_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Shift+Z"), state, false, false);
  ASSERT_EQ(shift_redo_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(shift_redo_dispatch.command_id,
            quader::quader_command::kEditRedo.string());

  ASSERT_TRUE(
      editor.commands().execute(quader::quader_command::kEditRedo).ok());

  ASSERT_TRUE(editor.preferences()
                  .set_shortcut(quader::quader_command::kEditUndo, "Ctrl+Alt+Z")
                  .ok());
  const quader::QuaderViewportKeybindingDispatch rebound_undo_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Alt+Z"), state, false, false);
  ASSERT_EQ(rebound_undo_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(rebound_undo_dispatch.command_id,
            quader::quader_command::kEditUndo.string());
}

