#ifndef NDEBUG
TEST(EditorApiTests, DebugCopySelectionJsonCopiesEdgeSelectionAndReportsStatus) {
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  ASSERT_TRUE(editor.commands()
                  .set_keybinding_storage_path(
                      keybinding_test_path("debug-copy-selection-json"))
                  .ok());

  std::string copied_text;
  editor.dev_tools().set_runtime_hooks(quader::QuaderDevToolsRuntimeHooks{
      .set_clipboard_text =
          [&copied_text](std::string_view text, std::string &error_message) {
            copied_text = std::string(text);
            error_message.clear();
            return true;
          },
  });

  const quader::QuaderModelingObjectRef box =
      create_selected_box(editor, "Dev Copy Edge Box");
  ASSERT_TRUE(editor.selection().select_edge(box, 1, 2).ok());
  const quader::QuaderSelectionSummary selected =
      editor.selection().summary();
  ASSERT_EQ(selected.mode, quader::QuaderSelectionMode::Edge);
  ASSERT_EQ(selected.selected_edge_count, 1u);

  const quader::QuaderApiVoidResult copied =
      editor.commands().execute(quader::quader_command::kDevCopySelectionJson);
  ASSERT_TRUE(copied.ok()) << copied.error_message();
  EXPECT_FALSE(copied.changed());
  EXPECT_EQ(copied.error_message(), "Copied selection JSON to clipboard.");
  ASSERT_TRUE(editor.commands().last_status().has_value());
  expect_same_api_status(*editor.commands().last_status(), copied);
  ASSERT_FALSE(copied_text.empty());

  const nlohmann::ordered_json root = nlohmann::ordered_json::parse(copied_text);
  EXPECT_EQ(root.at("kind"), "quader.dev.selection");
  EXPECT_EQ(root.at("version"), 1);

  const nlohmann::ordered_json &selection = root.at("selection");
  EXPECT_EQ(selection.at("mode"), "edge");
  EXPECT_TRUE(selection.at("hasSelection").get<bool>());
  EXPECT_EQ(selection.at("active").at("kind"), "edge");
  EXPECT_EQ(selection.at("active").at("modelingObjectId"),
            box.modeling_object_id);
  EXPECT_EQ(selection.at("counts").at("objects"), 1);
  EXPECT_EQ(selection.at("counts").at("edges"), 1);
  ASSERT_EQ(selection.at("objects").size(), 1u);

  const nlohmann::ordered_json &object = selection.at("objects").at(0);
  EXPECT_EQ(object.at("modelingObjectId"), box.modeling_object_id);
  EXPECT_EQ(object.at("entity"), box.entity);
  EXPECT_EQ(object.at("name"), "Dev Copy Edge Box");
  EXPECT_TRUE(object.at("selected").get<bool>());
  ASSERT_EQ(object.at("selection").at("edges").size(), 1u);
  EXPECT_EQ(object.at("selection").at("edges").at(0).at("a"), 1);
  EXPECT_EQ(object.at("selection").at("edges").at(0).at("b"), 2);
  ASSERT_EQ(object.at("selectedGeometry").at("edges").size(), 1u);
  const nlohmann::ordered_json &edge =
      object.at("selectedGeometry").at("edges").at(0);
  EXPECT_EQ(edge.at("a"), 1);
  EXPECT_EQ(edge.at("b"), 2);
  EXPECT_TRUE(edge.at("aPosition").contains("x"));
  EXPECT_TRUE(edge.at("bPosition").contains("x"));
}
#endif

TEST(EditorApiTests, GlobalCommandKeybindingsDoNotStealTextInputOrViewportOnlyShortcuts) {
  const std::filesystem::path path =
      keybinding_test_path("global-command-context");
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path(path).ok());

  quader::ViewportToolState state;
  const quader::QuaderViewportKeybindingDispatch unavailable_undo =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Z"), state, false, false);
  EXPECT_EQ(unavailable_undo.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);

  const quader::QuaderViewportKeybindingDispatch text_input_undo =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Ctrl+Z"), state, false, true);
  EXPECT_EQ(text_input_undo.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);

  create_selected_box(editor, "Pivot Shortcut Box");
  ASSERT_TRUE(editor.commands().remove_shortcut(
      quader::quader_command::kParentToActive).ok());
  ASSERT_TRUE(editor.commands().set_shortcut(
      quader::quader_command::kToolsActivatePivot, "P").ok());

  const quader::QuaderViewportKeybindingDispatch pivot_without_viewport_focus =
          editor.commands().dispatch_viewport_input_binding(
              single_input_chord("P"), state, false, false);
  EXPECT_EQ(pivot_without_viewport_focus.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);

  const quader::QuaderViewportKeybindingDispatch pivot_with_viewport_focus =
          editor.commands().dispatch_viewport_input_binding(
              single_input_chord("P"), state, true, false);
  ASSERT_EQ(pivot_with_viewport_focus.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::ViewportShortcut);
  EXPECT_EQ(pivot_with_viewport_focus.shortcut.kind,
            quader::ViewportShortcutKind::ActivateTool);
  EXPECT_EQ(pivot_with_viewport_focus.shortcut.tool,
            quader::ViewportToolId::Pivot);
}

TEST(EditorApiTests,
     PrimitiveToolShortcutsResolveWithoutSameContextConflicts) {
  const std::filesystem::path path =
      keybinding_test_path("primitive-tool-shortcuts");
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path(path).ok());

  struct PrimitiveBinding {
    quader::QuaderCommandId command;
    std::string_view shortcut;
    std::string_view kind;
  };
  constexpr std::array kBindings{
      PrimitiveBinding{quader::quader_command::kToolsActivateCreateBox,
                       "Shift+B", "box"},
      PrimitiveBinding{quader::quader_command::kToolsActivateCreateCylinder,
                       "Shift+C", "cylinder"},
      PrimitiveBinding{quader::quader_command::kToolsActivateCreateSphere,
                       "Shift+S", "sphere"},
  };
  const auto catalog = editor.commands().keybinding_catalog();
  for (const PrimitiveBinding &binding : kBindings) {
    SCOPED_TRACE(binding.kind);
    EXPECT_EQ(editor.commands().shortcut_for(binding.command), binding.shortcut);
    const auto *entry = find_keybinding_catalog_entry(catalog, binding.command.string());
    ASSERT_NE(entry, nullptr);
    EXPECT_EQ(entry->default_shortcut, binding.shortcut);
    EXPECT_FALSE(entry->customized);
    EXPECT_FALSE(entry->unassigned);
    const auto analysis = editor.commands().analyze_shortcut_assignment(
        entry->key, binding.shortcut);
    EXPECT_TRUE(analysis.conflicts.empty());
    for (int owner = 0; owner < 3; ++owner) {
      const quader::QuaderViewportKeybindingContext context{
          .outliner_focused = owner == 1, .editor_focused = owner == 2};
      const auto dispatch = editor.commands().dispatch_viewport_input_binding(
          single_input_chord(binding.shortcut), {}, owner == 0, false, context);
      ASSERT_EQ(dispatch.kind,
                quader::QuaderViewportKeybindingDispatch::Kind::Command);
      EXPECT_NE(std::find(entry->target_ids.begin(), entry->target_ids.end(),
                          dispatch.command_id), entry->target_ids.end());
      ASSERT_TRUE(editor.commands().execute(dispatch.command_id).ok());
      EXPECT_EQ(editor.tools().active_primitive_type(), binding.kind);
      EXPECT_EQ(editor.commands().dispatch_viewport_input_binding(
                    single_input_chord(binding.shortcut), {}, owner == 0, true,
                    context).kind,
                quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
    }
    EXPECT_EQ(editor.commands().dispatch_viewport_input_binding(
                  single_input_chord(binding.shortcut), {}, true, false,
                  {.navigation_active = true}).kind,
              quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  }

  EXPECT_TRUE(editor.commands()
                  .shortcut_for(quader::quader_command::kToolsActivateCut)
                  .empty());
  EXPECT_EQ(editor.commands().shortcut_for(quader::quader_command::kModelingBridge),
            "B");
}

TEST(EditorApiTests, PrimitiveBoxCompatibilityAliasPreservesLegacyOverrides) {
  constexpr auto kBox = quader::quader_command::kToolsActivateCreateBox;
  constexpr auto kLegacy = quader::quader_command::kToolsActivateCreatePrimitive;
  struct LegacyCase {
    std::string_view entries;
    std::string_view expected;
  };
  constexpr std::array kCases{
      LegacyCase{R"([{"command":"tools.activate.create_primitive","key":"Ctrl+Alt+F21","when":"true"}])",
                 "Ctrl+Alt+F21"},
      LegacyCase{R"([{"command":"-tools.activate.create_primitive"}])", ""},
      LegacyCase{R"([{"command":"tools.activate.create_primitive","key":"Ctrl+Alt+F21"},{"command":"tools.activate.create_box","key":"Ctrl+Alt+F22"}])",
                 "Ctrl+Alt+F22"},
      LegacyCase{R"([{"command":"tools.activate.create_box","key":"Ctrl+Alt+F22"},{"command":"-tools.activate.create_primitive"}])",
                 ""},
      LegacyCase{R"([{"command":"-tools.activate.create_box"},{"command":"tools.activate.create_primitive","key":"Ctrl+Alt+F21"}])",
                 "Ctrl+Alt+F21"},
      LegacyCase{R"([{"command":"tools.activate.create_primitive","key":"Ctrl+Alt+F21 B"}])",
                 "Ctrl+Alt+F21 B"},
  };
  const auto path = keybinding_test_path("primitive-box-compatibility");
  for (const LegacyCase &test : kCases) {
    SCOPED_TRACE(test.entries);
    {
      std::ofstream file(path, std::ios::binary);
      file << test.entries;
    }
    CommandTestHarness harness;
    auto &editor = harness.editor;
    ASSERT_TRUE(editor.commands().set_keybinding_storage_path(path).ok());
    const auto catalog = editor.commands().keybinding_catalog();
    const auto *box = find_keybinding_catalog_entry(catalog, kBox.string());
    ASSERT_NE(box, nullptr);
    EXPECT_EQ(find_keybinding_catalog_entry(catalog, kLegacy.string()), box);
    EXPECT_EQ(box->action_id, kBox.string());
    EXPECT_EQ(box->label, "Create Box");
    EXPECT_EQ(box->target_ids.size(), 2u);
    EXPECT_EQ(box->shortcut, test.expected);
    EXPECT_EQ(box->default_shortcut, "Shift+B");
    EXPECT_TRUE(box->customized);
    EXPECT_EQ(editor.commands().shortcut_for(kLegacy), test.expected);
    EXPECT_EQ(editor.commands().shortcut_for(kBox), test.expected);
    EXPECT_EQ(read_text_file(path), test.entries);

    ASSERT_TRUE(editor.commands().execute(
        quader::quader_command::kToolsActivateCreateCylinder).ok());
    ASSERT_EQ(editor.tools().active_primitive_type(), "cylinder");
    if (!test.expected.empty()) {
      const auto sequence = quader::quader_input_parse_shortcut(test.expected);
      ASSERT_TRUE(sequence.has_value());
      for (std::size_t index = 0; index < sequence->size(); ++index) {
        const auto dispatched = editor.commands().dispatch_viewport_input_binding(
            sequence->at(index),
            {.active_tool = quader::ViewportToolId::CreatePrimitive}, true, false);
        if (index + 1u < sequence->size()) {
          EXPECT_EQ(dispatched.kind,
                    quader::QuaderViewportKeybindingDispatch::Kind::PendingChord);
        } else {
          ASSERT_EQ(dispatched.kind,
                    quader::QuaderViewportKeybindingDispatch::Kind::Command);
          ASSERT_TRUE(editor.commands().execute(dispatched.command_id).ok());
          EXPECT_EQ(editor.tools().active_primitive_type(), "box");
        }
      }
    } else {
      EXPECT_EQ(editor.commands().dispatch_viewport_input_binding(
                    single_input_chord("Shift+B"), {}, true, false).kind,
                quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
    }
    ASSERT_TRUE(editor.commands().execute(
        quader::quader_command::kToolsActivateCreateSphere).ok());
    ASSERT_TRUE(editor.commands().execute(kLegacy).ok());
    EXPECT_EQ(editor.tools().active_primitive_type(), "box");
    EXPECT_EQ(read_text_file(path), test.entries);
  }
  std::filesystem::remove(path);
}

TEST(EditorApiTests, PrimitiveSpecificOverridesAndAliasEditsSurviveReload) {
  constexpr auto kBox = quader::quader_command::kToolsActivateCreateBox;
  constexpr auto kLegacy = quader::quader_command::kToolsActivateCreatePrimitive;
  constexpr auto kCylinder = quader::quader_command::kToolsActivateCreateCylinder;
  constexpr auto kSphere = quader::quader_command::kToolsActivateCreateSphere;
  const auto path = keybinding_test_path("primitive-shape-overrides");
  CommandTestHarness harness;
  auto &commands = harness.editor.commands();
  ASSERT_TRUE(commands.set_keybinding_storage_path(path).ok());
  ASSERT_TRUE(commands.set_shortcut(kCylinder, "Ctrl+Alt+F22").ok());
  ASSERT_TRUE(commands.remove_shortcut(kSphere).ok());
  ASSERT_TRUE(commands.set_shortcut(kLegacy, "Ctrl+Alt+F23 B").ok());
  CommandTestHarness reloaded_harness;
  auto &reloaded = reloaded_harness.editor.commands();
  ASSERT_TRUE(reloaded.set_keybinding_storage_path(path).ok());
  EXPECT_EQ(reloaded.shortcut_for(kBox), "Ctrl+Alt+F23 B");
  EXPECT_EQ(reloaded.shortcut_for(kLegacy), "Ctrl+Alt+F23 B");
  EXPECT_EQ(reloaded.shortcut_for(kCylinder), "Ctrl+Alt+F22");
  EXPECT_TRUE(reloaded.shortcut_for(kSphere).empty());
  ASSERT_TRUE(reloaded.remove_shortcut(kLegacy).ok());
  CommandTestHarness removed_harness;
  auto &removed = removed_harness.editor.commands();
  ASSERT_TRUE(removed.set_keybinding_storage_path(path).ok());
  EXPECT_TRUE(removed.shortcut_for(kBox).empty());
  EXPECT_TRUE(removed.shortcut_for(kLegacy).empty());
  EXPECT_EQ(removed.shortcut_for(kCylinder), "Ctrl+Alt+F22");
  EXPECT_TRUE(removed.shortcut_for(kSphere).empty());
  const auto catalog = removed.keybinding_catalog();
  const auto *box = find_keybinding_catalog_entry(catalog, kBox.string());
  ASSERT_NE(box, nullptr);
  ASSERT_TRUE(removed.reset_action_shortcut(box->key).ok());
  EXPECT_EQ(removed.shortcut_for(kBox), "Shift+B");
  EXPECT_EQ(removed.shortcut_for(kLegacy), "Shift+B");
  EXPECT_EQ(removed.shortcut_for(kCylinder), "Ctrl+Alt+F22");
  EXPECT_TRUE(removed.shortcut_for(kSphere).empty());
  std::filesystem::remove(path);
}

TEST(EditorApiTests, PrimitiveHemisphereHasTypedLocalizedSphereBinding) {
  constexpr auto kHemisphere = quader::quader_command::kToolsTogglePrimitiveHemisphere;
  constexpr auto kHide = quader::quader_command::kSceneHideSelection;
  CommandTestHarness harness;
  auto &editor = harness.editor;
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path({}).ok());
  EXPECT_TRUE(typed_command_ids().contains(std::string(kHemisphere.string())));
  ASSERT_TRUE(editor.commands().descriptor(kHemisphere));
  EXPECT_FALSE(editor.commands().descriptor(kHemisphere)->enabled);
  EXPECT_FALSE(editor.commands().execute(kHemisphere).ok());
  const auto catalog = editor.commands().keybinding_catalog();
  const auto *entry = find_keybinding_catalog_entry(catalog, kHemisphere.string());
  const auto *hide = find_keybinding_catalog_entry(catalog, kHide.string());
  ASSERT_NE(entry, nullptr);
  ASSERT_NE(hide, nullptr);
  EXPECT_EQ(entry->label, "Toggle Primitive Hemisphere");
  EXPECT_EQ(entry->localization_key,
            "keybindings.target.tools.primitive.toggle_hemisphere.label");
  EXPECT_EQ(entry->context, quader::QuaderKeybindingContextKind::ModalTool);
  EXPECT_EQ(entry->scope_id, "viewport.tool.modal");
  EXPECT_EQ(entry->shortcut, "H");
  EXPECT_EQ(entry->default_shortcut, "H");
  EXPECT_FALSE(entry->customized);
  EXPECT_FALSE(quader::keybinding_detail::when_expressions_overlap(entry->when, hide->when));
  const auto analysis = editor.commands().analyze_shortcut_assignment(entry->key, "H");
  ASSERT_TRUE(analysis.ok) << analysis.message;
  EXPECT_TRUE(analysis.conflicts.empty());
  const auto *presentation = quader::find_command_presentation(kHemisphere);
  ASSERT_NE(presentation, nullptr);
  EXPECT_EQ(presentation->domain, quader::CommandPresentationDomain::Create);
  EXPECT_EQ(presentation->activation, quader::CommandPresentationActivation::Toggle);
  EXPECT_EQ(presentation->palette_policy, quader::CommandPalettePolicy::ContextOnly);
  EXPECT_TRUE(quader::has_command_presentation_surface(
      *presentation, quader::CommandPresentationSurface::ToolSettings));

  (void)create_selected_box(editor);
  EXPECT_EQ(editor.commands().dispatch_viewport_input_binding(
      single_input_chord("H"), {}, true, false).command_id, kHide.string());
  ASSERT_TRUE(editor.tools().activate(quader::ViewportToolId::CreatePrimitive).ok());
  const quader::ViewportToolState state{
      .active_tool = quader::ViewportToolId::CreatePrimitive};
  for (const char *kind : {"box", "cylinder", "cone", "torus"}) {
    SCOPED_TRACE(kind);
    ASSERT_TRUE(editor.tools().set_setting("create_primitive", "primitive.type", kind).ok());
    EXPECT_FALSE(editor.commands().descriptor(kHemisphere)->enabled);
    const auto before = quader::test::capture_command_observable_state(editor);
    EXPECT_FALSE(editor.commands().execute(kHemisphere).ok());
    EXPECT_EQ(quader::test::capture_command_observable_state(editor), before);
    EXPECT_EQ(editor.commands().dispatch_viewport_input_binding(
        single_input_chord("H"), state, true, false).command_id, kHide.string());
  }
  ASSERT_TRUE(editor.tools().set_setting("create_primitive", "primitive.type", "sphere").ok());
  EXPECT_TRUE(editor.commands().descriptor(kHemisphere)->enabled);
  EXPECT_EQ(editor.commands().dispatch_viewport_input_binding(
      single_input_chord("H"), state, true, false).command_id, kHemisphere.string());
  EXPECT_FALSE(editor.commands().resolve_immediate_global_command(
      single_input_chord("H"), state, false));
  ASSERT_TRUE(editor.tools().cancel_active_tool_preview().ok());
  EXPECT_EQ(editor.commands().dispatch_viewport_input_binding(
      single_input_chord("H"), {}, true, false).command_id, kHide.string());
  EXPECT_NE(editor.commands().dispatch_viewport_input_binding(
      single_input_chord("H"), state, true, false).command_id, kHemisphere.string());
}

