TEST(EditorApiTests, PrimitiveFlipFacesSequenceUsesSharedViewportDispatcher) {
  constexpr auto kFlip = quader::quader_command::kToolsFlipPrimitiveFaces;
  CommandTestHarness harness;
  auto &editor = harness.editor;
  ASSERT_TRUE(editor.commands()
                  .set_keybinding_storage_path(
                      keybinding_test_path("primitive-flip-sequence"))
                  .ok());
  ASSERT_TRUE(editor.preferences().set_shortcut(kFlip, "Ctrl+K D").ok());
  ASSERT_TRUE(
      editor.tools().activate(quader::ViewportToolId::CreatePrimitive).ok());
  const quader::ViewportToolState state{
      .active_tool = quader::ViewportToolId::CreatePrimitive};
  std::vector<quader::QuaderInputChord> suppressed;
  double linear_wheel = 0.0;
  double radial_wheel = 0.0;
  const auto resolve = [&](std::string_view shortcut, bool focused = true,
                           bool text = false, bool navigation = false) {
    quader::ViewportInputFrame input;
    input.viewport_focused = focused;
    input.text_input_active = text;
    input.navigation_active = navigation;
    input.pressed_input_chords = {single_input_chord(shortcut)};
    input.released_input_chords = input.pressed_input_chords;
    quader::ViewportKeybindingResolver::resolve(
        editor, state, input, suppressed, linear_wheel, radial_wheel);
    return input;
  };
  const auto flip_value = [&] {
    return find_tool_setting_control(editor.tools().active_settings(),
                                     "primitive.flip_faces")
        ->bool_value;
  };
  for (const bool expected : {true, false}) {
    EXPECT_TRUE(resolve("Ctrl+K").keybinding_input_consumed);
    ASSERT_TRUE(editor.commands().has_pending_keybinding_chord());
    EXPECT_NE(flip_value(), expected);
    const auto completed = resolve("D");
    EXPECT_TRUE(completed.keybinding_input_consumed);
    EXPECT_FALSE(completed.quick_pivot_pressed);
    EXPECT_EQ(flip_value(), expected);
    EXPECT_FALSE(editor.commands().has_pending_keybinding_chord());
  }
  for (const auto [focused, text, navigation] :
       {std::array{false, false, false}, std::array{true, true, false},
        std::array{true, false, true}}) {
    (void)resolve("Ctrl+K");
    ASSERT_TRUE(editor.commands().has_pending_keybinding_chord());
    (void)resolve("D", focused, text, navigation);
    EXPECT_FALSE(editor.commands().has_pending_keybinding_chord());
    EXPECT_FALSE(flip_value());
  }
  (void)resolve("Ctrl+K");
  ASSERT_TRUE(editor.commands().has_pending_keybinding_chord());
  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive", "primitive.type", "sphere")
                  .ok());
  (void)resolve("D");
  EXPECT_FALSE(editor.commands().has_pending_keybinding_chord());
  EXPECT_TRUE(flip_value());
  (void)resolve("Ctrl+K");
  ASSERT_TRUE(editor.commands().has_pending_keybinding_chord());
  ASSERT_TRUE(editor.tools().cancel_active_tool_preview().ok());
  (void)resolve("D");
  EXPECT_FALSE(editor.commands().has_pending_keybinding_chord());
  EXPECT_FALSE(editor.commands().descriptor(kFlip)->enabled);
}

TEST(EditorApiTests, PrimitiveFlipFacesUpdatesLiveCubeWithinCreationHistory) {
  constexpr auto kFlip = quader::quader_command::kToolsFlipPrimitiveFaces;
  const auto *contract =
      quader::test::find_command_behavior_contract(kFlip.string());
  ASSERT_NE(contract, nullptr);
  auto fixture = quader::test::CommandBehaviorFixture::create(*contract);
  auto &editor = fixture->editor();
  ASSERT_TRUE(editor.commands().set_keybinding_storage_path({}).ok());
  using Domain = quader::test::CommandObservableDomain;
  const auto before = quader::test::capture_command_observable_state(editor);
  const auto selected = selected_entities(editor);
  ASSERT_EQ(selected.size(), 1u);

  quader::ViewportInputFrame input;
  input.viewport_focused = true;
  input.pressed_input_chords = {single_input_chord("Shift+F")};
  ASSERT_TRUE(editor.tools()
                  .begin_primitive_cube_resize(quader::QuaderPrimitiveCubeAxis::X,
                                               true)
                  .ok());
  input.active_transform_drag = true;
  std::vector<quader::QuaderInputChord> suppressed;
  double linear_wheel = 0.0;
  double radial_wheel = 0.0;
  quader::ViewportKeybindingResolver::resolve(
      editor, {.active_tool = quader::ViewportToolId::CreatePrimitive}, input,
      suppressed, linear_wheel, radial_wheel);
  ASSERT_TRUE(input.keybinding_input_consumed);
  EXPECT_TRUE(input.resolved_shortcuts.empty());
  ASSERT_TRUE(editor.tools().live_primitive_cube().has_value());
  EXPECT_TRUE(editor.tools().live_primitive_cube()->flip_faces);
  EXPECT_TRUE(editor.tools().live_primitive_cube()->resizing);
  ASSERT_TRUE(editor.tools().end_primitive_cube_resize().ok());
  const auto flipped = quader::test::capture_command_observable_state(editor);
  EXPECT_NE(flipped.domain(Domain::Geometry), before.domain(Domain::Geometry));
  EXPECT_EQ(selected_entities(editor), selected);
  EXPECT_EQ(flipped.domain(Domain::History), before.domain(Domain::History));

  ASSERT_TRUE(editor.commands().execute(kFlip).ok());
  EXPECT_EQ(quader::test::capture_command_observable_state(editor)
                .domain(Domain::Geometry),
            before.domain(Domain::Geometry));
  ASSERT_TRUE(editor.commands().execute(kFlip).ok());
  ASSERT_TRUE(editor.history().undo().ok());
  EXPECT_EQ(editor.query().entities().size(), 0u);
  EXPECT_FALSE(editor.history().can_undo());
  ASSERT_TRUE(editor.history().redo().ok());
  EXPECT_EQ(selected_entities(editor), selected);
  EXPECT_EQ(quader::test::capture_command_observable_state(editor)
                .domain(Domain::Geometry),
            flipped.domain(Domain::Geometry));
}


TEST(EditorApiTests, SphereTypeSettingsRetainParametersAndPresentationOrigin) {
  CommandTestHarness harness;
  auto &editor = harness.editor;
  ASSERT_TRUE(editor.tools().begin_primitive_creation(
      quader::QuaderPrimitiveCreationShape::Sphere).ok());
  const auto origin = editor.tools().active_settings_presentation_origin();
  auto settings = editor.tools().active_settings();
  ASSERT_GE(settings.controls.size(), 4u);
  EXPECT_EQ(settings.controls.front().id, "primitive.sphere.type");
  const auto *type = find_tool_setting_control(settings, "primitive.sphere.type");
  ASSERT_NE(type, nullptr);
  EXPECT_EQ(type->choice_value, "uv");
  EXPECT_EQ(type->choice_presentation,
            quader::QuaderToolSettingChoicePresentation::Dropdown);
  ASSERT_EQ(type->choices.size(), 2u);
  EXPECT_EQ(type->choices[0].id, "uv");
  EXPECT_EQ(type->choices[0].label, "UV Sphere");
  EXPECT_DOUBLE_EQ(type->choices[0].value, 0.0);
  EXPECT_EQ(type->choices[1].id, "quad");
  EXPECT_EQ(type->choices[1].label, "Quad Sphere");
  EXPECT_DOUBLE_EQ(type->choices[1].value, 1.0);
  EXPECT_EQ(find_tool_setting_control(settings, "primitive.sphere.subdivision"),
            nullptr);
  ASSERT_TRUE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.radial_segments", 12.0).ok());
  ASSERT_TRUE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.rings", 8.0).ok());
  ASSERT_TRUE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.type", "quad").ok());
  settings = editor.tools().active_settings();
  EXPECT_EQ(find_tool_setting_control(settings, "primitive.sphere.radial_segments"),
            nullptr);
  EXPECT_EQ(find_tool_setting_control(settings, "primitive.sphere.rings"), nullptr);
  const auto *subdivision =
      find_tool_setting_control(settings, "primitive.sphere.subdivision");
  ASSERT_NE(subdivision, nullptr);
  EXPECT_EQ(subdivision->label, "Subdivision");
  EXPECT_DOUBLE_EQ(subdivision->number_value, 3.0);
  EXPECT_DOUBLE_EQ(subdivision->min_value, 1.0);
  EXPECT_DOUBLE_EQ(subdivision->max_value, 6.0);
  EXPECT_DOUBLE_EQ(subdivision->step, 1.0);
  EXPECT_NE(find_tool_setting_control(settings, "primitive.sphere.hemisphere"),
            nullptr);
  EXPECT_NE(find_tool_setting_control(settings, "primitive.flip_faces"), nullptr);
  ASSERT_TRUE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.subdivision", 4.0).ok());
  const auto revision = editor.tools().active_settings_revision();
  for (const double invalid : {0.0, 7.0, 2.5,
                              std::numeric_limits<double>::infinity(),
                              std::numeric_limits<double>::quiet_NaN()}) {
    EXPECT_FALSE(editor.tools().set_setting(
        "create_primitive", "primitive.sphere.subdivision", invalid).ok());
  }
  for (const double invalid : {-1.0, 2.0, 0.5,
                              std::numeric_limits<double>::infinity()}) {
    EXPECT_FALSE(editor.tools().set_setting(
        "create_primitive", "primitive.sphere.type", invalid).ok());
  }
  EXPECT_FALSE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.type", "unknown").ok());
  EXPECT_FALSE(editor.tools().set_setting(
      "move", "primitive.sphere.type", "uv").ok());
  EXPECT_FALSE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.rings", 10.0).ok());
  EXPECT_FALSE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.type", 1.0).changed());
  for (int frame = 0; frame < 32; ++frame) {
    EXPECT_EQ(editor.tools().active_settings_revision(), revision);
    EXPECT_EQ(editor.tools().active_settings_presentation_origin(), origin);
  }

  ASSERT_TRUE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.type", 0.0).ok());
  settings = editor.tools().active_settings();
  const auto *radial =
      find_tool_setting_control(settings, "primitive.sphere.radial_segments");
  const auto *rings = find_tool_setting_control(settings, "primitive.sphere.rings");
  ASSERT_NE(radial, nullptr);
  ASSERT_NE(rings, nullptr);
  EXPECT_DOUBLE_EQ(radial->number_value, 12.0);
  EXPECT_DOUBLE_EQ(rings->number_value, 8.0);
  ASSERT_TRUE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.type", 1.0).ok());
  settings = editor.tools().active_settings();
  subdivision = find_tool_setting_control(settings, "primitive.sphere.subdivision");
  ASSERT_NE(subdivision, nullptr);
  EXPECT_DOUBLE_EQ(subdivision->number_value, 4.0);
  ASSERT_TRUE(editor.tools().reset_active_settings().ok());
  settings = editor.tools().active_settings();
  type = find_tool_setting_control(settings, "primitive.sphere.type");
  ASSERT_NE(type, nullptr);
  EXPECT_EQ(type->choice_value, "uv");
  EXPECT_EQ(editor.tools().active_settings_presentation_origin(), origin);
  ASSERT_TRUE(editor.tools().set_setting(
      "create_primitive", "primitive.sphere.type", "quad").ok());
  settings = editor.tools().active_settings();
  subdivision = find_tool_setting_control(settings, "primitive.sphere.subdivision");
  ASSERT_NE(subdivision, nullptr);
  EXPECT_DOUBLE_EQ(subdivision->number_value, 3.0);
  ASSERT_TRUE(editor.tools().cancel_active_tool_preview().ok());
}

TEST(EditorApiTests,
     CreatePrimitiveExposesDynamicSettingsAndRemainsActiveUntilCancel) {
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  const auto control = [](const quader::QuaderToolSettingsTarget &target,
                          std::string_view id) {
    return std::find_if(target.controls.begin(), target.controls.end(),
                        [id](const auto &item) { return item.id == id; });
  };

  ASSERT_TRUE(
      editor.tools().activate(quader::ViewportToolId::CreatePrimitive).ok());
  EXPECT_EQ(editor.tools().active_tool(), "create_primitive");
  const quader::ViewportToolState box_tool_state{
      .active_tool = quader::ViewportToolId::CreatePrimitive,
  };
  const quader::QuaderViewportKeybindingDispatch space_without_focus =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Space"), box_tool_state, false, false);
  EXPECT_EQ(space_without_focus.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  const quader::QuaderViewportKeybindingDispatch removed_enter_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Enter"), box_tool_state, true, false);
  EXPECT_EQ(removed_enter_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  const quader::QuaderViewportKeybindingDispatch space_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Space"), box_tool_state, true, false);
  ASSERT_EQ(space_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(space_dispatch.command_id,
            quader::quader_command::kToolsApplyPrimitiveCreation.string());
  const quader::QuaderViewportKeybindingDispatch escape_without_focus =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Escape"), box_tool_state, false, false);
  EXPECT_EQ(escape_without_focus.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::NoMatch);
  const quader::QuaderViewportKeybindingDispatch escape_dispatch =
      editor.commands().dispatch_viewport_input_binding(
          single_input_chord("Escape"), box_tool_state, true, false);
  ASSERT_EQ(escape_dispatch.kind,
            quader::QuaderViewportKeybindingDispatch::Kind::Command);
  EXPECT_EQ(escape_dispatch.command_id,
            quader::quader_command::kToolsCancelPrimitiveCreation.string());
  quader::QuaderToolSettingsTarget settings = editor.tools().active_settings();
  EXPECT_TRUE(settings.active);
  EXPECT_EQ(settings.description,
            "Draw a footprint, set its height, and refine the primitive before "
            "applying it.");
  EXPECT_TRUE(settings.can_reset);
  EXPECT_TRUE(settings.apply_visible);
  EXPECT_FALSE(settings.can_apply);
  EXPECT_TRUE(settings.can_cancel);
  EXPECT_EQ(control(settings, "primitive.type"), settings.controls.end());
  EXPECT_EQ(settings.title, "Create Box");
  EXPECT_EQ(editor.tools().active_primitive_default_name(), "Box");
  ASSERT_NE(control(settings, "primitive.box.subdivisions_x"),
            settings.controls.end());
  ASSERT_NE(control(settings, "primitive.box.subdivisions_y"),
            settings.controls.end());
  ASSERT_NE(control(settings, "primitive.box.subdivisions_z"),
            settings.controls.end());
  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive",
                               "primitive.box.subdivisions_x", 4.0)
                  .ok());
  EXPECT_FALSE(editor.tools().commit_active_tool_preview().ok());
  EXPECT_EQ(editor.tools().active_tool(), "create_primitive");

  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive", "primitive.type",
                               "cylinder")
                  .ok());
  EXPECT_EQ(editor.tools().active_tool(), "create_primitive");
  EXPECT_EQ(editor.query().tool_status().active_tool,
            quader::QuaderViewportTool::CreatePrimitive);
  settings = editor.tools().active_settings();
  ASSERT_NE(control(settings, "primitive.cylinder.side_count"),
            settings.controls.end());
  EXPECT_EQ(settings.title, "Create Cylinder");
  EXPECT_EQ(control(settings, "primitive.type"), settings.controls.end());
  ASSERT_NE(control(settings, "primitive.cylinder.caps"),
            settings.controls.end());
  ASSERT_NE(control(settings, "primitive.flip_faces"),
            settings.controls.end());
  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive",
                               "primitive.cylinder.side_count", 12.0)
                  .ok());
  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive",
                               "primitive.cylinder.caps", false)
                  .ok());

  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive", "primitive.type", "sphere")
                  .ok());
  EXPECT_EQ(editor.tools().active_tool(), "create_primitive");
  EXPECT_EQ(editor.query().tool_status().active_tool,
            quader::QuaderViewportTool::CreatePrimitive);
  settings = editor.tools().active_settings();
  ASSERT_NE(control(settings, "primitive.sphere.radial_segments"),
            settings.controls.end());
  EXPECT_EQ(settings.title, "Create Sphere");
  EXPECT_EQ(control(settings, "primitive.type"), settings.controls.end());
  ASSERT_NE(control(settings, "primitive.sphere.rings"),
            settings.controls.end());
  ASSERT_NE(control(settings, "primitive.sphere.hemisphere"),
            settings.controls.end());
  ASSERT_NE(control(settings, "primitive.flip_faces"),
            settings.controls.end());

  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive", "primitive.type", "cone")
                  .ok());
  EXPECT_EQ(editor.tools().active_primitive_type(), "cone");
  EXPECT_EQ(editor.tools().active_primitive_default_name(), "Cone");
  settings = editor.tools().active_settings();
  ASSERT_NE(control(settings, "primitive.cone.side_count"),
            settings.controls.end());
  ASSERT_NE(control(settings, "primitive.cone.caps"),
            settings.controls.end());
  ASSERT_NE(control(settings, "primitive.flip_faces"),
            settings.controls.end());
  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive",
                               "primitive.cone.side_count", 7.0)
                  .ok());
  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive", "primitive.cone.caps",
                               false)
                  .ok());

  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive", "primitive.type", "torus")
                  .ok());
  EXPECT_EQ(editor.tools().active_primitive_type(), "torus");
  EXPECT_EQ(editor.tools().active_primitive_default_name(), "Torus");
  settings = editor.tools().active_settings();
  ASSERT_NE(control(settings, "primitive.torus.major_segments"),
            settings.controls.end());
  ASSERT_NE(control(settings, "primitive.torus.minor_segments"),
            settings.controls.end());
  const auto tube_ratio =
      control(settings, "primitive.torus.tube_radius_ratio");
  ASSERT_NE(tube_ratio, settings.controls.end());
  EXPECT_DOUBLE_EQ(tube_ratio->number_value, 0.2);
  EXPECT_DOUBLE_EQ(tube_ratio->min_value, 0.01);
  EXPECT_DOUBLE_EQ(tube_ratio->max_value, 0.49);
  EXPECT_DOUBLE_EQ(tube_ratio->step, 0.01);
  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive",
                               "primitive.torus.major_segments", 24.0)
                  .ok());
  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive",
                               "primitive.torus.minor_segments", 10.0)
                  .ok());
  ASSERT_TRUE(editor.tools()
                  .set_setting("create_primitive",
                               "primitive.torus.tube_radius_ratio", 0.3)
                  .ok());

  const quader::QuaderApiVoidResult reset =
      editor.tools().reset_active_settings();
  ASSERT_TRUE(reset.ok()) << reset.error_message();
  EXPECT_TRUE(reset.changed());
  EXPECT_EQ(editor.tools().active_primitive_type(), "torus");
  settings = editor.tools().active_settings();
  const quader::QuaderToolSettingControl *reset_major =
      find_tool_setting_control(settings, "primitive.torus.major_segments");
  const quader::QuaderToolSettingControl *reset_minor =
      find_tool_setting_control(settings, "primitive.torus.minor_segments");
  const quader::QuaderToolSettingControl *reset_ratio =
      find_tool_setting_control(settings, "primitive.torus.tube_radius_ratio");
  ASSERT_NE(reset_major, nullptr);
  ASSERT_NE(reset_minor, nullptr);
  ASSERT_NE(reset_ratio, nullptr);
  EXPECT_DOUBLE_EQ(reset_major->number_value, 32.0);
  EXPECT_DOUBLE_EQ(reset_minor->number_value, 12.0);
  EXPECT_DOUBLE_EQ(reset_ratio->number_value, 0.2);

  const quader::QuaderApiVoidResult canceled =
      editor.tools().cancel_active_tool_preview();
  EXPECT_TRUE(canceled.ok()) << canceled.error_message();
  EXPECT_EQ(editor.tools().active_tool(), "select");
  EXPECT_TRUE(editor.tools().active_primitive_default_name().empty());
  EXPECT_FALSE(editor.tools().active_settings().active);
}

TEST(EditorApiTests,
     ActiveSettingsRevisionSkipsStableReadsAndTracksPrimitiveChanges) {
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;

  const std::uint64_t initial = editor.tools().active_settings_revision();
  EXPECT_EQ(editor.tools().active_settings_revision(), initial);

  ASSERT_TRUE(
      editor.tools().activate(quader::ViewportToolId::CreatePrimitive).ok());
  const std::uint64_t activated = editor.tools().active_settings_revision();
  EXPECT_GT(activated, initial);
  EXPECT_EQ(editor.tools().active_settings_revision(), activated);

  const quader::QuaderApiVoidResult changed = editor.tools().set_setting(
      "create_primitive", "primitive.box.subdivisions_x", 4.0);
  ASSERT_TRUE(changed.ok()) << changed.error_message();
  EXPECT_TRUE(changed.changed());
  const std::uint64_t setting_changed =
      editor.tools().active_settings_revision();
  EXPECT_GT(setting_changed, activated);

  const quader::QuaderApiVoidResult unchanged = editor.tools().set_setting(
      "create_primitive", "primitive.box.subdivisions_x", 4.0);
  ASSERT_TRUE(unchanged.ok()) << unchanged.error_message();
  EXPECT_FALSE(unchanged.changed());
  EXPECT_EQ(editor.tools().active_settings_revision(), setting_changed);

  ASSERT_TRUE(editor.tools().cancel_active_tool_preview().ok());
  EXPECT_GT(editor.tools().active_settings_revision(), setting_changed);
}

