TEST(EditorApiTests, EdgeBevelLearningMaximumReportsChangeWithoutGeometryChange) {
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  const auto source = editor.modeling().create_box(
      {.min = {-0.25f, -0.125f, -0.25f},
       .max = {0.25f, 2.125f, 0.25f}}, "Bevel Maximum Feedback Source");
  ASSERT_TRUE(source.ok()) << source.error_message();
  ASSERT_TRUE(editor.selection().set_mode(quader::QuaderSelectionMode::Edge).ok());
  ASSERT_TRUE(editor.selection().select_edge(source.value(), 2, 3).ok());
  ASSERT_TRUE(editor.commands().execute(
      editor.commands().command_id_for_modeling_action("bevel_edges")).ok());
  const auto width = [&editor]() {
    const auto target = editor.tools().active_settings();
    const auto *control = find_tool_setting_control(
        target, "operation.edge_bevel.width");
    EXPECT_NE(control, nullptr);
    return control != nullptr ? *control : quader::QuaderToolSettingControl{};
  };
  const auto initial = width();
  ASSERT_LT(initial.max_value, 1.0);
  ASSERT_DOUBLE_EQ(initial.number_value, initial.max_value);

  // One segment has no interior profile points. This accepted parameter
  // change invalidates the old bound without changing the displayed geometry.
  ASSERT_TRUE(editor.tools().set_setting(
      "edge_bevel", "operation.edge_bevel.profile", 0.6).ok());
  ASSERT_DOUBLE_EQ(width().max_value, 512.0);
  ASSERT_DOUBLE_EQ(width().number_value, initial.number_value);
  const auto geometry_before = editor.query().compiled_object_mesh(source.value());
  ASSERT_TRUE(geometry_before.has_value());
  const auto settings_revision = editor.tools().active_settings_revision();

  const auto learned = editor.tools().set_setting(
      "edge_bevel", "operation.edge_bevel.width", 1.0);
  ASSERT_TRUE(learned.ok()) << learned.error_message();
  EXPECT_TRUE(learned.changed());
  EXPECT_DOUBLE_EQ(width().number_value, initial.number_value);
  EXPECT_DOUBLE_EQ(width().max_value, initial.max_value);
  const auto geometry_after = editor.query().compiled_object_mesh(source.value());
  ASSERT_TRUE(geometry_after.has_value());
  EXPECT_EQ(geometry_after->indices, geometry_before->indices);
  ASSERT_EQ(geometry_after->vertices.size(), geometry_before->vertices.size());
  for (std::size_t index = 0; index < geometry_before->vertices.size(); ++index) {
    const auto &before = geometry_before->vertices[index].position;
    const auto &after = geometry_after->vertices[index].position;
    EXPECT_FLOAT_EQ(after.x, before.x);
    EXPECT_FLOAT_EQ(after.y, before.y);
    EXPECT_FLOAT_EQ(after.z, before.z);
  }
  EXPECT_GT(editor.tools().active_settings_revision(), settings_revision);

  const auto learned_revision = editor.tools().active_settings_revision();
  const auto assets_revision = editor.revisions().asset_revision;
  const auto repeated = editor.tools().set_setting(
      "edge_bevel", "operation.edge_bevel.width", 1.0);
  ASSERT_TRUE(repeated.ok()) << repeated.error_message();
  EXPECT_FALSE(repeated.changed());
  EXPECT_EQ(editor.tools().active_settings_revision(), learned_revision);
  EXPECT_EQ(editor.revisions().asset_revision, assets_revision);
  ASSERT_TRUE(editor.tools().cancel_active_tool_preview().ok());
}

TEST(EditorApiTests, EdgeBevelSelectionRestartRecalculatesUsefulWidth) {
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  const auto source = editor.modeling().create_box(
      {.min = {-0.25f, -0.125f, -0.25f},
       .max = {0.25f, 2.125f, 0.25f}}, "Bevel Source");
  const auto smaller = editor.modeling().create_box(
      {.min = {-0.125f, -0.125f, -0.125f},
       .max = {0.125f, 2.125f, 0.125f}}, "Smaller Bevel Source");
  ASSERT_TRUE(source.ok());
  ASSERT_TRUE(smaller.ok());
  ASSERT_TRUE(editor.selection().set_mode(quader::QuaderSelectionMode::Edge).ok());
  ASSERT_TRUE(editor.selection().select_edge(source.value(), 2, 3).ok());
  ASSERT_TRUE(editor.commands().execute(
      editor.commands().command_id_for_modeling_action("bevel_edges")).ok());
  const auto revision = editor.tools().active_settings_revision();
  const auto same_selection =
      editor.selection().select_edge(source.value(), 2, 3);
  ASSERT_TRUE(same_selection.ok()) << same_selection.error_message();
  EXPECT_FALSE(same_selection.changed());
  const auto retained_target = editor.tools().active_settings();
  const auto *retained_width = find_tool_setting_control(
      retained_target, "operation.edge_bevel.width");
  ASSERT_NE(retained_width, nullptr);
  EXPECT_NEAR(retained_width->max_value, 0.4995, 1.0e-7);
  EXPECT_EQ(editor.tools().active_settings_revision(), revision);
  ASSERT_TRUE(editor.selection().select_edge(smaller.value(), 2, 3).ok());
  EXPECT_GT(editor.tools().active_settings_revision(), revision);
  auto target = editor.tools().active_settings();
  const auto *width = find_tool_setting_control(target,
                                               "operation.edge_bevel.width");
  ASSERT_NE(width, nullptr);
  EXPECT_NEAR(width->number_value, 0.24975, 1.0e-7);
  EXPECT_DOUBLE_EQ(width->number_value, width->max_value);
  const double accepted_width = width->number_value;
  ASSERT_TRUE(editor.selection().select_edge(source.value(), 2, 3).ok());
  target = editor.tools().active_settings();
  width = find_tool_setting_control(target, "operation.edge_bevel.width");
  ASSERT_NE(width, nullptr);
  EXPECT_DOUBLE_EQ(width->max_value, 512.0);
  EXPECT_DOUBLE_EQ(width->number_value, accepted_width);
  ASSERT_TRUE(editor.tools().cancel_active_tool_preview().ok());
}


TEST(EditorApiTests,
     ArrayBoundsVisibilitySettingsAreVisualOnlyAndRemembered) {
  for (const std::string_view tool_id :
       {"linear_array", "radial_array", "path_array"}) {
    SCOPED_TRACE(tool_id);
    CommandTestHarness harness;
    quader::QuaderEditorApi &editor = harness.editor;
    EXPECT_FALSE(editor.tools().active_array_bounding_box_dimensions().has_value());
    (void)create_selected_box(editor, "Array Bounds Source");
    if (tool_id == "path_array") {
      const auto curve = editor.modeling().create_curve({
          .points = {{.position = {0.0f, 0.0f, 0.0f}},
                     {.position = {5.0f, 0.0f, 0.0f}}},
          .name = "Array Bounds Path",
      });
      ASSERT_TRUE(curve.ok()) << curve.error_message();
      ASSERT_TRUE(editor.selection().select_object(curve.value()).ok());
    }
    ASSERT_TRUE(editor.tools().activate(tool_id).ok());
    const std::string setting_id =
        std::string(tool_id) + ".show_bounding_box_dimensions";
    auto settings = editor.tools().active_settings();
    const auto *control = find_tool_setting_control(settings, setting_id);
    ASSERT_NE(control, nullptr);
    EXPECT_EQ(control->kind, quader::QuaderToolSettingControlKind::Toggle);
    EXPECT_EQ(control->label, "Bounding Box and Dimensions");
    EXPECT_TRUE(control->bool_value);
    EXPECT_EQ(editor.tools().active_array_bounding_box_dimensions(), true);
    const auto before = editor.revisions();
    const auto history_before = editor.query().history();
    const auto settings_revision = editor.tools().active_settings_revision();

    const auto hidden = editor.tools().set_setting(tool_id, setting_id, false);
    ASSERT_TRUE(hidden.ok()) << hidden.error_message();
    EXPECT_TRUE(hidden.changed());
    EXPECT_EQ(editor.tools().active_array_bounding_box_dimensions(), false);
    EXPECT_GT(editor.tools().active_settings_revision(), settings_revision);
    const auto hidden_revision = editor.tools().active_settings_revision();
    settings = editor.tools().active_settings();
    control = find_tool_setting_control(settings, setting_id);
    ASSERT_NE(control, nullptr);
    EXPECT_FALSE(control->bool_value);
    EXPECT_FALSE(editor.tools().set_setting(tool_id, setting_id, false).changed());
    EXPECT_FALSE(editor.tools().set_setting(tool_id, setting_id, 2.0).ok());
    EXPECT_EQ(editor.tools().active_settings_revision(), hidden_revision);
    const auto after = editor.revisions();
    EXPECT_EQ(after.scene_revision, before.scene_revision);
    EXPECT_EQ(after.asset_revision, before.asset_revision);
    EXPECT_EQ(after.modeling_content_revision, before.modeling_content_revision);
    EXPECT_EQ(after.modeling_selection_revision, before.modeling_selection_revision);

    ASSERT_TRUE(editor.tools().cancel_active_tool_preview().ok());
    EXPECT_FALSE(editor.tools().active_array_bounding_box_dimensions().has_value());
    ASSERT_TRUE(editor.tools().activate(tool_id).ok());
    EXPECT_EQ(editor.tools().active_array_bounding_box_dimensions(), false);
    ASSERT_TRUE(editor.tools().reset_active_settings().ok());
    EXPECT_EQ(editor.tools().active_array_bounding_box_dimensions(), true);
    settings = editor.tools().active_settings();
    control = find_tool_setting_control(settings, setting_id);
    ASSERT_NE(control, nullptr);
    EXPECT_TRUE(control->bool_value);

    const auto history_after = editor.query().history();
    EXPECT_EQ(history_after.can_undo, history_before.can_undo);
    EXPECT_EQ(history_after.can_redo, history_before.can_redo);
    EXPECT_EQ(history_after.undo_label, history_before.undo_label);
    EXPECT_EQ(history_after.redo_label, history_before.redo_label);
  }
}

TEST(EditorApiTests,
     LinearArrayToolAcceptsMultipleMeshesAndKeepsSharedEndpointFixed) {
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;

  EXPECT_FALSE(editor.tools().can_activate(quader::ViewportToolId::LinearArray));
  const std::optional<quader::QuaderCommandDescriptor> unavailable =
      command_descriptor(editor,
                         quader::quader_command::kToolsActivateLinearArray);
  ASSERT_TRUE(unavailable.has_value());
  EXPECT_FALSE(unavailable->enabled);
  EXPECT_TRUE(unavailable->shortcut.empty());

  const quader::QuaderModelingObjectRef source =
      create_selected_box(editor, "Linear Array Tool Source");
  const quader::QuaderModelingObjectRef second =
      create_selected_box(editor, "Linear Array Tool Second");
  ASSERT_TRUE(editor.scene()
                  .set_transform(second.entity,
                                 {.position = {10.0f, 0.0f, 0.0f}})
                  .ok());
  ASSERT_TRUE(editor.selection()
                  .select_objects({source.entity, second.entity}, source.entity)
                  .ok());
  ASSERT_TRUE(editor.tools().can_activate(quader::ViewportToolId::LinearArray));
  const quader::QuaderApiVoidResult activated =
      editor.tools().activate(quader::ViewportToolId::LinearArray);
  ASSERT_TRUE(activated.ok()) << activated.error_message();
  EXPECT_EQ(editor.tools().active_tool(), "linear_array");

  const quader::QuaderToolSettingsTarget initial_settings =
      editor.tools().active_settings();
  ASSERT_TRUE(initial_settings.active);
  EXPECT_TRUE(initial_settings.preview_active);
  EXPECT_EQ(initial_settings.tool_id, "linear_array");
  EXPECT_EQ(initial_settings.title, "Linear Array");
  EXPECT_EQ(initial_settings.description,
            "Drag an endpoint to create evenly spaced copies along a line.");
  EXPECT_TRUE(initial_settings.can_reset);
  EXPECT_TRUE(initial_settings.can_apply);
  EXPECT_TRUE(initial_settings.can_cancel);
  const quader::QuaderToolSettingControl *count =
      find_tool_setting_control(initial_settings, "linear_array.count");
  ASSERT_NE(count, nullptr);
  EXPECT_EQ(count->kind, quader::QuaderToolSettingControlKind::Number);
  EXPECT_EQ(count->label, "Num Copies");
  EXPECT_DOUBLE_EQ(count->number_value, 4.0);
  EXPECT_DOUBLE_EQ(count->min_value, 2.0);
  EXPECT_DOUBLE_EQ(count->max_value, 128.0);

  std::vector<quader::QuaderToolPreviewMesh> previews =
      editor.render().tool_preview_meshes();
  ASSERT_EQ(previews.size(), 2u);
  EXPECT_EQ(previews[0].source_entity, second.entity);
  EXPECT_EQ(previews[1].source_entity, source.entity);
  ASSERT_EQ(previews[0].instance_transforms.size(), 3u);
  ASSERT_EQ(previews[1].instance_transforms.size(), 3u);
  EXPECT_NEAR(previews[0].instance_transforms[0].values[12], 22.0f,
              kTestPositionEpsilon);
  EXPECT_NEAR(previews[0].instance_transforms[1].values[12], 34.0f,
              kTestPositionEpsilon);
  EXPECT_NEAR(previews[0].instance_transforms[2].values[12], 46.0f,
              kTestPositionEpsilon);
  EXPECT_NEAR(previews[1].instance_transforms[0].values[12], 12.0f,
              kTestPositionEpsilon);
  EXPECT_NEAR(previews[1].instance_transforms[2].values[12], 36.0f,
              kTestPositionEpsilon);

  const quader::QuaderApiVoidResult changed_count = editor.tools().set_setting(
      "linear_array", "linear_array.count", 6.0);
  ASSERT_TRUE(changed_count.ok()) << changed_count.error_message();
  previews = editor.render().tool_preview_meshes();
  ASSERT_EQ(previews.size(), 2u);
  ASSERT_EQ(previews[0].instance_transforms.size(), 5u);
  ASSERT_EQ(previews[1].instance_transforms.size(), 5u);
  EXPECT_NEAR(previews[0].instance_transforms.front().values[12], 17.2f,
              kTestPositionEpsilon);
  EXPECT_NEAR(previews[0].instance_transforms.back().values[12], 46.0f,
              kTestPositionEpsilon);
  EXPECT_NEAR(previews[1].instance_transforms.front().values[12], 7.2f,
              kTestPositionEpsilon);
  EXPECT_NEAR(previews[1].instance_transforms.back().values[12], 36.0f,
              kTestPositionEpsilon);

  const quader::QuaderApiVoidResult reset =
      editor.tools().reset_active_settings();
  ASSERT_TRUE(reset.ok()) << reset.error_message();
  EXPECT_TRUE(reset.changed());
  const quader::QuaderToolSettingsTarget reset_settings =
      editor.tools().active_settings();
  const quader::QuaderToolSettingControl *reset_count =
      find_tool_setting_control(reset_settings, "linear_array.count");
  ASSERT_NE(reset_count, nullptr);
  EXPECT_DOUBLE_EQ(reset_count->number_value, 4.0);
  previews = editor.render().tool_preview_meshes();
  ASSERT_EQ(previews.size(), 2u);
  EXPECT_EQ(previews[0].instance_transforms.size(), 3u);
  EXPECT_EQ(previews[1].instance_transforms.size(), 3u);

  const quader::QuaderApiVoidResult canceled =
      editor.tools().cancel_active_tool_preview();
  ASSERT_TRUE(canceled.ok()) << canceled.error_message();
  EXPECT_EQ(editor.tools().active_tool(), "select");
  EXPECT_TRUE(editor.render().tool_preview_meshes().empty());
  EXPECT_EQ(editor.query().entities().size(), 2u);
}

TEST(EditorApiTests, LinearArrayToolApplyUsesTheAtomicModelingCommand) {
  CommandTestHarness harness;
  quader::QuaderEditorApi &editor = harness.editor;
  const quader::QuaderModelingObjectRef primary =
      create_selected_box(editor, "Linear Array Apply Primary");
  const quader::QuaderModelingObjectRef second =
      create_selected_box(editor, "Linear Array Apply Second");
  ASSERT_TRUE(editor.scene()
                  .set_transform(second.entity,
                                 {.position = {10.0f, 0.0f, 0.0f}})
                  .ok());
  ASSERT_TRUE(editor.selection()
                  .select_objects({primary.entity, second.entity},
                                  primary.entity)
                  .ok());
  ASSERT_TRUE(editor.tools().activate(quader::ViewportToolId::LinearArray).ok());
  ASSERT_TRUE(editor.tools()
                  .set_setting("linear_array", "linear_array.count", 3.0)
                  .ok());
  const quader::QuaderApiVoidResult applied =
      editor.tools().commit_active_tool_preview();
  ASSERT_TRUE(applied.ok()) << applied.error_message();
  EXPECT_TRUE(applied.changed());
  EXPECT_EQ(editor.query().entities().size(), 6u);
  EXPECT_EQ(selected_entities(editor).size(), 6u);
  EXPECT_EQ(editor.query().history().undo_label, "Linear Array");
  EXPECT_EQ(editor.tools().active_tool(), "select");

  std::vector<float> positions;
  std::optional<quader::QuaderEntitySnapshot> active;
  for (const quader::QuaderEntitySnapshot &entity : editor.query().entities()) {
    positions.push_back(entity.transform.position.x);
    if (entity.active) {
      active = entity;
    }
  }
  std::sort(positions.begin(), positions.end());
  ASSERT_EQ(positions.size(), 6u);
  EXPECT_NEAR(positions[0], 0.0f, kTestPositionEpsilon);
  EXPECT_NEAR(positions[1], 10.0f, kTestPositionEpsilon);
  EXPECT_NEAR(positions[2], 18.0f, kTestPositionEpsilon);
  EXPECT_NEAR(positions[3], 28.0f, kTestPositionEpsilon);
  EXPECT_NEAR(positions[4], 36.0f, kTestPositionEpsilon);
  EXPECT_NEAR(positions[5], 46.0f, kTestPositionEpsilon);
  ASSERT_TRUE(active.has_value());
  EXPECT_NEAR(active->transform.position.x, 36.0f, kTestPositionEpsilon);

  ASSERT_TRUE(editor.history().undo().ok());
  EXPECT_EQ(editor.query().entities().size(), 2u);
  ASSERT_TRUE(editor.history().redo().ok());
  EXPECT_EQ(editor.query().entities().size(), 6u);
  EXPECT_EQ(selected_entities(editor).size(), 6u);
}

