    expect_bounds_near(*after_bounds, *before_bounds);
    EXPECT_EQ(editor.query().history().undo_label, "Select Entities");
    ASSERT_TRUE(editor.history().undo().ok());
    EXPECT_EQ(editor.query().history().undo_label, "Set Pivot");
